import { ChatInput } from "@/components/shared/message/ChatInput";
import { ChatMessages } from "@/components/shared/message/ChatMessages";
import { mockCurrentUser } from "@/constants/mockChatData";
import getProfile from "@/helpers/getProfile";
import { myFetch } from "@/helpers/myFetch";

export const dynamic = "force-dynamic";

interface PageProps {
  params: Promise<{ id: string }>;
}

export default async function ChatDetailPage({ params }: PageProps) {
  const { id } = await params;
  // console.log(id);
  let activeUser = null;
  let currentUserId = "";
  let initialMessages = [];
  let loadingError = false;
  const profile = await getProfile();
// console.log(profile)
  try {
    if (profile?._id) {
      currentUserId = profile._id;

      // Fetch chat room details
      const room = await myFetch(`/chat/${id}`, {
        method: "GET",
        tags: ["chat", `chat-${id}`],
        cache: "no-store",
      });
      if (room?.success) {
        activeUser = room.data;

        // Fetch initial messages
        const msgRes = await myFetch(`/message/${id}?page=1`, {
          method: "GET",
          tags: ["message", `message-${id}`],
          cache: "no-store",
        });
        // console.log(msgRes, "msgRes");
        if (msgRes?.success) {
          initialMessages = msgRes.data || [];
        }
      }
    }
  } catch (error) {
    console.error("Failed to fetch chat details on server:", error);
    loadingError = true;
  }
// console.log(activeUser, "activeUser")
  if (loadingError || !activeUser) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center bg-[#F8FAFC] h-full p-8 text-center">
        <div className="w-16 h-16 rounded-2xl bg-red-100 border border-red-200 flex items-center justify-center text-red-500 mb-4 shadow-lg shadow-red-500/5">
          <span className="font-black text-2xl">!</span>
        </div>
        <h2 className="text-gray-900 font-bold text-lg mb-2">
          Conversation Not Found
        </h2>
        <p className="text-gray-500 text-sm max-w-xs mx-auto">
          We couldn't retrieve the details for this chat. It may have been
          deleted or moved.
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-[#F8FAFC] border-l border-gray-200">
      {/* ── Chat Messages (Scrolling Area) ── */}
      <div className="flex-1 min-h-0 overflow-hidden relative">
        <ChatMessages
          chatId={id}
          currentUserId={currentUserId}
          activeUser={activeUser}
          initialMessages={initialMessages}
        />
      </div>

      {/* ── Chat Input (Fixed Bottom) ── */}
      <div className="shrink-0 bg-white">
        <ChatInput chatId={id} activeUser={activeUser} profile={profile} />
      </div>

      {/* Aesthetic Border Highlight */}
      <div className="absolute top-0 inset-x-0 h-px bg-gray-200 pointer-events-none" />
    </div>
  );
}

"use client";

import { ChatSidebar } from "@/components/shared/message/ChatSidebar";
import { useEffect, useMemo, useState } from "react";
import { usePathname } from "next/navigation";
import Spinner from "@/components/shared/Spinner";
import { io } from "socket.io-client";
import getProfile from "@/helpers/getProfile";
import { myFetch } from "@/helpers/myFetch";

export default function MessageLayoutWrapper({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const isChatRoomActive = useMemo(() => {
    const segments = pathname.split("/").filter(Boolean);
    return segments.length > 1;
  }, [pathname]);

  const [search, setSearch] = useState("");
  const [userId, setUser] = useState(null);
  const [chatRooms, setChatRooms] = useState<any[]>([]);
  const [currentUserId, setCurrentUserId] = useState<string>("");
  const [loading, setLoading] = useState(true);
  const socket = useMemo(
    () =>
      io(
        process.env.NEXT_PUBLIC_SOCKET_URL ??
          process.env.SOCKET_URL ??
          "http://10.10.26.159:5000",
      ),
    [],
  );

  useEffect(() => {
    const fetchUser = async () => {
      const user = await getProfile();
      setUser(user?._id);
    };

    fetchUser();
  }, []);

  useEffect(() => {
    socket.on(`chatList::${userId}`, (data) => {
      // console.log(data, 'chat room data received');
      if (!data) return;

      setChatRooms((prev) => {
        let updatedRooms = [...prev];
        const incomingRooms = Array.isArray(data) ? data : [data];

        incomingRooms.forEach((newRoom) => {
          if (!newRoom?._id) return;

          const roomIndex = updatedRooms.findIndex(
            (r) => r._id === newRoom._id,
          );
          if (roomIndex !== -1) {
            // Update existing room with new data, merging fields
            updatedRooms[roomIndex] = {
              ...updatedRooms[roomIndex],
              ...newRoom,
            };
          } else {
            // Add new room to the list
            updatedRooms = [newRoom, ...updatedRooms];
          }
        });

        // Keep the list sorted by most recent message
        return updatedRooms.sort((a, b) => {
          const timeA = a.lastMessage?.createdAt
            ? new Date(a.lastMessage.createdAt).getTime()
            : 0;
          const timeB = b.lastMessage?.createdAt
            ? new Date(b.lastMessage.createdAt).getTime()
            : 0;
          return timeB - timeA;
        });
      });
    });

    return () => {
      socket.off(`chatList::${userId}`);
    };
  }, [socket, userId]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const profile = await getProfile();
        if (profile?._id) {
          setCurrentUserId(profile._id);
          const rooms = await myFetch(`/chat?searchTerm=${search}`, {
            method: "GET",
            tags: ["chat"],
            cache: "no-store",
          });
          if (rooms?.success) {
            const sortedRooms = [...(rooms.data || [])].sort((a, b) => {
              const timeA = a.lastMessage?.createdAt
                ? new Date(a.lastMessage.createdAt).getTime()
                : 0;
              const timeB = b.lastMessage?.createdAt
                ? new Date(b.lastMessage.createdAt).getTime()
                : 0;
              return timeB - timeA;
            });
            setChatRooms(sortedRooms);
          }
        }
      } catch (error) {
        console.error("Failed to fetch chat data:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [search]);

  if (loading) {
    return <Spinner />;
  }

  return (
    <div className="flex md:max-w-270 mx-auto overflow-hidden bg-white h-[calc(100vh-64px)]">
      {/* Sidebar - Persistent */}
      <div
        className={`w-full lg:w-1/3 xl:w-1/4 shrink-0 h-full lg:border-r lg:border-gray-200 ${isChatRoomActive ? "hidden lg:block" : "block"}`}
      >
        <ChatSidebar
          chatRooms={chatRooms}
          currentUserId={currentUserId}
          search={search}
          setSearch={setSearch}
        />
      </div>

      {/* Main Content (Conversations) */}
      <div
        className={`flex-1 h-full relative overflow-hidden bg-[#F8FAFC] ${isChatRoomActive ? "block" : "hidden lg:block"}`}
      >
        {children}
      </div>
    </div>
  );
}

