"use client";

import { useEffect, useRef, useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { ChevronDown, ChevronRight, Lock, Menu, X } from "lucide-react";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";
import { cn } from "@/lib/utils";
import { memberNav, type MemberNavItem } from "@/constants/member-nav";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import { LangSwitcher } from "./LangSwitcher";
import { NotificationsBell } from "./NotificationsBell";
import { UserMenu } from "./UserMenu";

interface MemberNavbarProps {
  lang: Locale;
  dict: Dictionary;
  currentUser: {
    email: string;
    username: string;
    displayName: string;
    avatarSeed: string;
  };
}

export function MemberNavbar({ lang, dict, currentUser }: MemberNavbarProps) {
  const pathname = usePathname();
  const [openKey, setOpenKey] = useState<string | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const closeTimer = useRef<number | null>(null);

  useEffect(() => () => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
  }, []);

  useEffect(() => {
    setDrawerOpen(false);
    setOpenKey(null);
  }, [pathname]);

  const handleEnter = (key: string) => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
    setOpenKey(key);
  };
  const handleLeave = () => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
    closeTimer.current = window.setTimeout(() => setOpenKey(null), 120);
  };

  const isActive = (href: string) => {
    const stripped = pathname.replace(new RegExp(`^/${lang}`), "") || "/";
    const target = href.split("?")[0];
    if (target === "/myHome") return stripped === "/myHome";
    return stripped === target || stripped.startsWith(`${target}/`);
  };

  return (
    <header className="sticky top-0 z-40 bg-brand text-white">
      <div className="container flex h-16 items-center gap-4">
        <Link
          href={`/${lang}/myHome`}
          className="shrink-0 select-none"
          aria-label="Viva Leve home"
        >
          <Image
            src="/logo.png"
            alt="Viva Leve"
            width={320}
            height={180}
            className="h-12 w-auto object-contain"
            priority
          />
        </Link>

        <nav className="hidden lg:flex flex-1 items-center justify-center gap-1">
          {memberNav.map((item) => (
            <DesktopNavItem
              key={item.labelKey}
              item={item}
              lang={lang}
              dict={dict}
              isOpen={openKey === item.labelKey}
              isActive={isActive(item.href)}
              onEnter={() => handleEnter(item.labelKey)}
              onLeave={handleLeave}
            />
          ))}
        </nav>

        <div className="ml-auto flex items-center gap-2">
          <NotificationsBell />
          <UserMenu
            lang={lang}
            dict={dict}
            email={currentUser.email}
            username={currentUser.username}
            displayName={currentUser.displayName}
            avatarSeed={currentUser.avatarSeed}
          />
          <LangSwitcher />
          <Sheet open={drawerOpen} onOpenChange={setDrawerOpen}>
            <SheetTrigger
              aria-label="Open menu"
              className="inline-flex size-9 lg:hidden items-center justify-center rounded-md text-white hover:bg-white/10"
            >
              <Menu className="size-5" />
            </SheetTrigger>
            <SheetContent side="right" className="w-80 p-0">
              <SheetHeader className="border-b px-5 py-4">
                <SheetTitle>{dict.nav.home}</SheetTitle>
              </SheetHeader>
              <div className="flex flex-col p-2">
                {memberNav.map((item) => (
                  <MobileNavItem
                    key={item.labelKey}
                    item={item}
                    lang={lang}
                    dict={dict}
                    onNavigate={() => setDrawerOpen(false)}
                  />
                ))}
              </div>
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
  );
}

interface DesktopNavItemProps {
  item: MemberNavItem;
  lang: Locale;
  dict: Dictionary;
  isOpen: boolean;
  isActive: boolean;
  onEnter: () => void;
  onLeave: () => void;
}

function DesktopNavItem({
  item,
  lang,
  dict,
  isOpen,
  isActive,
  onEnter,
  onLeave,
}: DesktopNavItemProps) {
  const label = dict.nav[item.labelKey];
  const hasChildren = (item.children?.length ?? 0) > 0;

  return (
    <div
      className="relative"
      onMouseEnter={onEnter}
      onMouseLeave={onLeave}
      onFocus={onEnter}
      onBlur={onLeave}
    >
      <Link
        href={`/${lang}${item.href}`}
        className={cn(
          "inline-flex items-center gap-1 rounded-md px-4 py-2 text-sm font-medium tracking-wide transition-colors outline-none focus-visible:bg-white/10",
          isActive ? "text-white" : "text-white/85 hover:text-white"
        )}
      >
        {label}
        {hasChildren ? <ChevronDown className="size-3.5 opacity-80" /> : null}
      </Link>
      {isActive ? (
        <span className="pointer-events-none absolute -bottom-px left-1/2 h-0.5 w-6 -translate-x-1/2 rounded-full bg-white" />
      ) : null}

      {hasChildren && isOpen ? (
        <div className="absolute left-1/2 top-full z-50 -translate-x-1/2 pt-2">
          <div className="min-w-56 rounded-lg border border-border bg-popover py-2 text-popover-foreground shadow-xl">
            {item.children!.map((child) => {
              const childLabel = dict.nav[child.labelKey];
              if (child.premiumLocked) {
                return (
                  <span
                    key={child.labelKey}
                    title={dict.nav.premiumLocked}
                    className="flex cursor-not-allowed items-center justify-between gap-2 px-4 py-2 text-sm text-muted-foreground"
                  >
                    {childLabel}
                    <Lock className="size-3.5" />
                  </span>
                );
              }
              return (
                <Link
                  key={child.labelKey}
                  href={`/${lang}${child.href}`}
                  className="flex items-center justify-between gap-2 px-4 py-2 text-sm text-foreground hover:bg-muted"
                >
                  {childLabel}
                </Link>
              );
            })}
          </div>
        </div>
      ) : null}
    </div>
  );
}

interface MobileNavItemProps {
  item: MemberNavItem;
  lang: Locale;
  dict: Dictionary;
  onNavigate: () => void;
}

function MobileNavItem({ item, lang, dict, onNavigate }: MobileNavItemProps) {
  const [open, setOpen] = useState(false);
  const label = dict.nav[item.labelKey];
  const hasChildren = (item.children?.length ?? 0) > 0;

  if (!hasChildren) {
    return (
      <Link
        href={`/${lang}${item.href}`}
        onClick={onNavigate}
        className="rounded-md px-3 py-2 text-sm font-medium hover:bg-muted"
      >
        {label}
      </Link>
    );
  }

  return (
    <div className="flex flex-col">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="flex items-center justify-between rounded-md px-3 py-2 text-sm font-medium hover:bg-muted"
      >
        <span>{label}</span>
        {open ? <X className="size-4" /> : <ChevronRight className="size-4" />}
      </button>
      {open ? (
        <div className="ml-3 flex flex-col border-l border-border pl-2">
          {item.children!.map((child) => {
            const childLabel = dict.nav[child.labelKey];
            if (child.premiumLocked) {
              return (
                <span
                  key={child.labelKey}
                  className="flex items-center justify-between gap-2 px-3 py-2 text-sm text-muted-foreground"
                >
                  {childLabel}
                  <Lock className="size-3.5" />
                </span>
              );
            }
            return (
              <Link
                key={child.labelKey}
                href={`/${lang}${child.href}`}
                onClick={onNavigate}
                className="rounded-md px-3 py-2 text-sm hover:bg-muted"
              >
                {childLabel}
              </Link>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { Bell, Loader2 } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { getNotifications } from "./action";

function timeAgo(date: Date) {
  const seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);
  let interval = seconds / 31536000;
  if (interval > 1) return Math.floor(interval) + "y ago";
  interval = seconds / 2592000;
  if (interval > 1) return Math.floor(interval) + "mo ago";
  interval = seconds / 86400;
  if (interval > 1) return Math.floor(interval) + "d ago";
  interval = seconds / 3600;
  if (interval > 1) return Math.floor(interval) + "h ago";
  interval = seconds / 60;
  if (interval > 1) return Math.floor(interval) + "m ago";
  return "just now";
}

export function NotificationsBell() {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchNotifs() {
      try {
        const data = await getNotifications();
        console.log("NOTIFICATIONS API RESPONSE:", data);
        setItems(data || []);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    }
    fetchNotifs();
  }, []);
  const unread = items.length;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        aria-label="Notifications"
        className="relative inline-flex size-9 items-center justify-center rounded-full text-white/90 hover:bg-white/10 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-white/40"
      >
        <Bell className="size-5" />
        {unread > 0 ? (
          <span className="absolute top-1 right-1 size-2 rounded-full bg-green-300" />
        ) : null}
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="w-80 p-2 rounded-2xl border-none shadow-2xl bg-white/95 backdrop-blur-xl"
      >
        <div className="px-3 py-2.5 mb-2 flex items-center justify-between border-b border-neutral-100">
          <span className="text-sm font-bold text-neutral-800 tracking-tight">
            Notifications
          </span>
          {unread > 0 && (
            <span className="text-[10px] font-bold px-2.5 py-0.5 rounded-full bg-[#429CA8]/10 text-[#429CA8] uppercase tracking-wider">
              {unread} New
            </span>
          )}
        </div>
        {loading ? (
          <div className="px-3 py-10 flex justify-center text-neutral-400">
            <Loader2 className="w-6 h-6 animate-spin" />
          </div>
        ) : items.length === 0 ? (
          <div className="px-3 py-10 text-sm text-neutral-400 text-center flex flex-col items-center gap-3">
            <div className="p-3 rounded-full bg-neutral-50 border border-neutral-100">
              <Bell className="w-6 h-6 opacity-30" />
            </div>
            <p className="font-medium">Nothing new right now</p>
          </div>
        ) : (
          <div className="space-y-1 max-h-[300px] overflow-y-auto">
            {items.map((n: any) => {
              const text = n.message || n.title || n.text || "New notification";
              let at = "just now";
              try {
                if (n.createdAt) {
                  at = timeAgo(new Date(n.createdAt));
                }
              } catch (e) {}

              return (
                <DropdownMenuItem
                  key={n._id || n.id || Math.random()}
                  className="cursor-pointer rounded-xl flex flex-col items-start gap-1 p-3 hover:bg-[#429CA8]/5 focus:bg-[#429CA8]/5 transition-all border border-transparent hover:border-[#429CA8]/10"
                >
                  <span className="text-sm font-semibold text-neutral-700">
                    {text}
                  </span>
                  <span className="text-[11px] font-bold text-[#429CA8]">
                    {at}
                  </span>
                </DropdownMenuItem>
              );
            })}
          </div>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

