    resolver: zodResolver(createEmailStepSchema(tValidation)),
    defaultValues: { email: "" },
  });
  const otpForm = useForm({
    resolver: zodResolver(createOtpSchema(tValidation)),
    defaultValues: { code: ["", "", "", "", "", ""] },
  });
