"use client";

import { useEffect, useMemo, useState } from "react";
import type { ButtonHTMLAttributes } from "react";
import { useRouter } from "next/navigation";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import {
  ArrowRight,
  BriefcaseBusiness,
  CheckCircle2,
  ChevronLeft,
  Heart,
  NotebookText,
  Ruler,
  ShieldCheck,
  Sparkles,
  UserRound,
  Weight,
} from "lucide-react";

import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { LangSwitcher } from "@/components/shared/LangSwitcher";
import { toast } from "sonner";
import { submitOnboardingAction } from "./action";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { createOnboardingSchema } from "@/schemas/auth/onboarding.schema";

const STORAGE_KEY = "vivaleve:onboarding:v1";
const steps = [
  "preferences",
  "location",
  "personal",
  "display",
  "physical",
  "professional",
  "about",
] as const;
type StepKey = (typeof steps)[number];

type OnboardingValues = {
  interestedIn: string;
  lookingFor: string;
  country: string;
  state: string;
  zipCode: string;
  nationality: string;
  dateOfBirth: string;
  livingWith: string;
  displayName: string;
  heightValue: string;
  heightUnit: string;
  weightValue: string;
  weightUnit: string;
  occupation: string;
  educationLevel: string;
  relationshipStatus: string;
  aboutYou: string;
};

const initialValues: OnboardingValues = {
  interestedIn: "woman",
  lookingFor: "man",
  country: "",
  state: "",
  zipCode: "",
  nationality: "",
  dateOfBirth: "",
  livingWith: "other",
  displayName: "",
  heightValue: "",
  heightUnit: "cm",
  weightValue: "",
  weightUnit: "kg",
  occupation: "",
  educationLevel: "college",
  relationshipStatus: "single",
  aboutYou: "",
};

interface Props {
  dict: any;
  lang: string;
}

export default function OnboardingFeature({ dict, lang }: Props) {
  const router = useRouter();
  const [step, setStep] = useState<StepKey>("preferences");
  const [success, setSuccess] = useState(false);
  const schema = useMemo(
    () =>
      createOnboardingSchema((key) => {
        const defaultMessages: Record<string, string> = {
          aboutMin: "Bio must be at least 40 characters.",
          aboutMax: "Bio cannot exceed 320 characters.",
          countryRequired: "Country is required.",
          stateRequired: "State is required.",
          zipRequired: "ZIP Code is required.",
          nationalityRequired: "Nationality is required.",
          dobRequired: "Date of Birth is required.",
          displayNameRequired: "Display Name is required.",
          heightRequired: "Height is required.",
          weightRequired: "Weight is required.",
          occupationRequired: "Occupation is required.",
          mustBeAdult: "You must be at least 18 years old.",
        };
        return dict.validation?.[key] || defaultMessages[key] || key;
      }),
    [dict],
  );

  const form = useForm<any>({
    resolver: zodResolver(schema),
    defaultValues: initialValues,
    mode: "onChange",
  });

  useEffect(() => {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return;
    try {
      form.reset({ ...initialValues, ...JSON.parse(raw) });
    } catch {
      window.localStorage.removeItem(STORAGE_KEY);
    }
  }, [form]);

  useEffect(() => {
    const sub = form.watch((value) => {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
    });
    return () => sub.unsubscribe();
  }, [form]);

  const values = form.watch();
  const completion = Math.round(
    (Object.values(values).filter(Boolean).length /
      Object.keys(initialValues).length) *
      100,
  );
  const isLast = step === "about";
  const currentIndex = steps.indexOf(step);

  const goNext = async () => {
    const fieldsByStep: Record<StepKey, string[]> = {
      preferences: ["interestedIn", "lookingFor"],
      location: ["country", "state", "zipCode", "nationality"],
      personal: ["dateOfBirth", "livingWith"],
      display: ["displayName"],
      physical: ["heightValue", "heightUnit", "weightValue", "weightUnit"],
      professional: ["occupation", "educationLevel"],
      about: ["relationshipStatus", "aboutYou"],
    };

    const ok = await form.trigger(fieldsByStep[step] as any);
    if (!ok) return;

    if (!isLast) {
      setStep(steps[currentIndex + 1]);
      return;
    }

    try {
      const formValues = form.getValues();
      const payload = {
        gender: formValues.interestedIn === "man" ? "MALE" : "FEMALE",
        lookingFor: formValues.lookingFor === "man" ? "MALE" : "FEMALE",
        country: formValues.country,
        state: formValues.state,
        zidCode: Number(formValues.zipCode) || 0,
        nationality: formValues.nationality,
        DOB: formValues.dateOfBirth
          ? new Date(formValues.dateOfBirth).toISOString()
          : new Date().toISOString(),
        livingWith: formValues.livingWith.toUpperCase(),
        displayName: formValues.displayName,
        height: Number(formValues.heightValue) || 0,
        weight: Number(formValues.weightValue) || 0,
        occupation: formValues.occupation,
        education: formValues.educationLevel.toUpperCase(),
        relationStatus: formValues.relationshipStatus.toUpperCase(),
        bio: formValues.aboutYou,
      };

      const res = await submitOnboardingAction(payload);

      if (res.success) {
        window.localStorage.removeItem(STORAGE_KEY);
        setSuccess(true);
        setTimeout(() => router.push(`/${lang}/myHome`), 1800);
      } else {
        toast.error(res.error || res.message || "Failed to submit onboarding");
      }
    } catch (err: any) {
      toast.error(err.message || "An unexpected error occurred");
    }
  };

  if (success) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[radial-gradient(circle_at_top,rgba(66,156,168,0.15),transparent_50%),linear-gradient(180deg,#ffffff,#f6fafb)] p-6">
        <Card className="w-full max-w-xl border-white/60 bg-white/90 p-10 text-center shadow-2xl">
          <div className="mx-auto mb-4 flex size-16 items-center justify-center rounded-full bg-[#429CA8]/10 text-[#429CA8]">
            <CheckCircle2 className="size-8" />
          </div>
          <h1 className="text-3xl font-bold tracking-tight text-neutral-900">
            {dict.onboarding?.successTitle}
          </h1>
          <p className="mt-2 text-sm text-neutral-600">
            {dict.onboarding?.successDescription}
          </p>
          <p className="mt-6 text-xs uppercase tracking-[0.3em] text-neutral-400">
            {dict.onboarding?.redirecting}
          </p>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top_left,rgba(66,156,168,0.18),transparent_35%),linear-gradient(180deg,#fff,#f6fafb)]">
      <div className="mx-auto grid min-h-screen max-w-7xl gap-6 px-4 py-4 lg:grid-cols-[0.95fr_1.05fr] lg:px-6 lg:py-6">
