"use client";

import { useState, useEffect } from "react";
import { createPortal } from "react-dom";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { ArrowLeft, X, ZoomIn, ZoomOut, Share2 } from "lucide-react";
import { cn } from "@/lib/utils";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import type { BlogPost, Comment, User } from "@/lib/types";
import { photoUrl } from "@/lib/image";
import { PostHeader } from "@/features/member/home/cards/PostHeader";
import { PostActions } from "@/features/member/home/cards/PostActions";
import { ReportContentModal } from "@/features/member/home/modals/ReportContentModal";

interface BlogDetailClientProps {
  lang: Locale;
  dict: Dictionary;
  blog: BlogPost;
  author: User;
  authorsMap: Record<string, { displayName: string; avatarSeed: string }>;
  likeCount: number;
  liked: boolean;
  comments: Comment[];
  currentUserAvatarSeed: string;
}

export function BlogDetailClient({
  lang,
  dict,
  blog,
  author,
  authorsMap,
  likeCount,
  liked,
  comments,
  currentUserAvatarSeed,
}: BlogDetailClientProps) {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [mounted, setMounted] = useState(false);
  const [isReportOpen, setIsReportOpen] = useState(false);
  const [copied, setCopied] = useState(false);

  useEffect(() => setMounted(true), []);

  useEffect(() => {
    if (!selectedImage) {
      setZoomLevel(1);
      return;
    }
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") setSelectedImage(null);
    };
    window.addEventListener("keydown", handleEsc);
    document.body.style.overflow = "hidden";
    return () => {
      window.removeEventListener("keydown", handleEsc);
      document.body.style.overflow = "unset";
    };
  }, [selectedImage]);

  const toggleZoom = () => setZoomLevel((z) => (z === 1 ? 2.5 : 1));

  const handleShare = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback: do nothing
    }
  };

  const formattedDate = new Intl.DateTimeFormat(
    lang === "pt" ? "pt-BR" : "en-US",
    { year: "numeric", month: "long", day: "numeric" },
  ).format(new Date(blog.createdAt));

  const count = blog.imageSeeds.length;

  return (
    <>
      <div className="container py-6 max-w-2xl">
        {/* Back */}
        <Link
          href={`/${lang}/blog`}
          className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors mb-5"
        >
          <ArrowLeft className="size-4" />
          {dict.blog.backToBlogs}
        </Link>

        <article className="overflow-hidden rounded-xl border border-border bg-card">
          <PostHeader user={author} lang={lang} />

          {/* Title + date */}
          <div className="px-4 pt-4 pb-2">
            <h1 className="text-xl font-bold leading-snug">{blog.title}</h1>
            <p className="text-xs text-muted-foreground mt-1">
              {formattedDate}
            </p>
          </div>

          {/* Images */}
          {count > 0 ? (
            <div
              className={cn(
                "mt-2 gap-1 px-4",
                count === 1 ? "flex" : "grid grid-cols-2",
              )}
            >
              {blog.imageSeeds.map((seed, i) => (
                <div
                  key={seed + i}
                  className="overflow-hidden rounded-md bg-muted aspect-5/3 cursor-pointer hover:opacity-90 transition-opacity"
                  onClick={() => setSelectedImage(seed)}
                >
                  <Image
                    src={photoUrl(seed, 800, 600)}
                    alt={blog.title}
                    width={800}
                    height={600}
                    className="size-full object-cover"
                    unoptimized
                  />
                </div>
              ))}
            </div>
          ) : null}

          {/* Full content */}
          <div className="px-4 py-5">
            <p className="text-sm text-foreground leading-relaxed whitespace-pre-wrap">
              {blog.content}
            </p>

            {/* Tags */}
            {blog.tags.length > 0 ? (
              <div className="flex flex-wrap gap-2 mt-5">
                {blog.tags.map((tag) => (
                  <span
                    key={tag}
                    className="text-xs px-2.5 py-1 rounded-full bg-brand/10 text-brand font-medium"
                  >
                    #{tag}
                  </span>
                ))}
              </div>
            ) : null}
          </div>

          {/* Share bar */}
          <div className="flex items-center justify-between border-t border-border px-4 py-2">
            <button
              type="button"
              onClick={() => setIsReportOpen(true)}
              className="text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              {dict.blog.report}
            </button>
            <button
              type="button"
              onClick={handleShare}
              className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors"
            >
              <Share2 className="size-4" />
              {copied ? "Copied!" : dict.blog.share}
            </button>
          </div>

          {/* Like + Comments */}
          <PostActions
            kind="blog"
            postId={blog.id}
            initialLikeCount={likeCount}
            initialLiked={liked}
            initialComments={comments}
            authors={authorsMap}
            currentUserAvatarSeed={currentUserAvatarSeed}
            commentPlaceholder={dict.blog.commentPlaceholder}
          />
        </article>
      </div>

      {/* Full-screen photo viewer */}
      {selectedImage && mounted
        ? createPortal(
            <div className="fixed inset-0 z-40 flex flex-col bg-black animate-in fade-in duration-200">
              <div className="absolute right-6 top-6 z-50 flex items-center gap-6 text-white/90">
                <button
                  onClick={() => setIsReportOpen(true)}
                  className="text-sm font-medium hover:text-white transition-colors"
                >
                  {dict.blog.report}
                </button>
                <button
                  onClick={toggleZoom}
                  className="hover:text-white transition-colors"
                >
                  {zoomLevel > 1 ? (
                    <ZoomOut className="size-5" />
                  ) : (
                    <ZoomIn className="size-5" />
                  )}
                </button>
                <button
                  onClick={() => setSelectedImage(null)}
                  className="hover:text-white transition-colors"
                >
                  <X className="size-6" />
                </button>
              </div>

              <div
                className={cn(
                  "relative flex h-full w-full items-center justify-center overflow-auto transition-all duration-300",
                  zoomLevel > 1 ? "cursor-zoom-out" : "cursor-zoom-in",
                )}
              >
                <div
                  className="relative transition-all duration-300 ease-out"
                  style={{
                    width: zoomLevel > 1 ? "250%" : "100%",
                    height: zoomLevel > 1 ? "250%" : "100%",
                    minHeight: "100vh",
                    minWidth: "100vw",
                  }}
                  onClick={(e) => {
                    if (e.target === e.currentTarget) toggleZoom();
                  }}
                >
                  <Image
                    src={photoUrl(selectedImage, 600, 600)}
                    alt=""
                    fill
                    className="object-contain blur-md opacity-50"
                    unoptimized
                  />
                  <Image
                    src={photoUrl(selectedImage, 1600, 1600)}
                    alt="Blog photo full screen"
                    fill
                    className="object-contain"
                    unoptimized
                    priority
                    onClick={toggleZoom}
                  />
                </div>
              </div>
            </div>,
            document.body,
          )
        : null}

      <ReportContentModal open={isReportOpen} onOpenChange={setIsReportOpen} />
    </>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import { ChevronDown, Loader2, PenLine } from "lucide-react";
import { toast } from "sonner";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import type { BlogPost, Comment, User } from "@/lib/types";
import { BlogCard } from "./components/BlogCard";
import { BlogSidebar, type BlogTab } from "./components/BlogSidebar";
import { PostBlogModal } from "./components/PostBlogModal";
import {
  getMyBlogsAction,
  getMyCommentedBlogsAction,
  getMyLikedBlogsAction,
} from "./actions";

type SortMode = "newest" | "popular";
type RemoteBlogTab = Exclude<BlogTab, "all">;

interface BlogTabPayload {
  blogs: BlogPost[];
  authorsMap: Record<string, User>;
  authorInfoMap: Record<string, { displayName: string; avatarSeed: string }>;
  likeMetaMap: Record<string, { count: number; liked: boolean }>;
  commentMap: Record<string, Comment[]>;
  commentCountMap: Record<string, number>;
}

interface BlogPageClientProps {
  lang: Locale;
  dict: Dictionary;
  blogs: BlogPost[];
  authorsMap: Record<string, User>;
  authorInfoMap: Record<string, { displayName: string; avatarSeed: string }>;
  likeMetaMap: Record<string, { count: number; liked: boolean }>;
  commentMap: Record<string, Comment[]>;
  commentCountMap?: Record<string, number>;
  currentUserAvatarSeed: string;
  currentUserId: string;
  recentBlogs: Pick<BlogPost, "id" | "title">[];
  totalBlogs: number;
}

export function BlogPageClient({
  lang,
  dict,
  blogs,
  authorsMap,
  authorInfoMap,
  likeMetaMap,
  commentMap,
  commentCountMap = {},
  currentUserAvatarSeed,
  recentBlogs,
  totalBlogs,
}: BlogPageClientProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [sortMode, setSortMode] = useState<SortMode>("newest");
  const [activeTab, setActiveTab] = useState<BlogTab>("all");
  const [isPostModalOpen, setIsPostModalOpen] = useState(false);
  const [isPending, startTransition] = useTransition();

  const [tabPayloads, setTabPayloads] = useState<
    Partial<Record<RemoteBlogTab, BlogTabPayload>>
  >({});

  const activePayload =
    activeTab === "all" ? undefined : tabPayloads[activeTab];
  const activeBlogs = activePayload?.blogs ?? blogs;
  const activeAuthorsMap = activePayload
    ? { ...activePayload.authorsMap, ...authorsMap }
    : authorsMap;
  const activeAuthorInfoMap = activePayload
    ? { ...activePayload.authorInfoMap, ...authorInfoMap }
    : authorInfoMap;
  const activeLikeMetaMap = activePayload
    ? { ...likeMetaMap, ...activePayload.likeMetaMap }
    : likeMetaMap;
  const activeCommentMap = activePayload
    ? { ...commentMap, ...activePayload.commentMap }
    : commentMap;
  const activeCommentCountMap = activePayload
    ? { ...commentCountMap, ...activePayload.commentCountMap }
    : commentCountMap;

  const handleTabChange = (tab: BlogTab) => {
    setActiveTab(tab);

    if (tab === "all") return;

    startTransition(async () => {
      const res =
        tab === "my"
          ? await getMyBlogsAction()
          : tab === "liked"
            ? await getMyLikedBlogsAction()
            : await getMyCommentedBlogsAction();

      if (!res.success) {
        toast.error(res.message ?? "Failed to load blogs");
        return;
      }

      setTabPayloads((previous) => ({
        ...previous,
        [tab]: {
          blogs: res.blogs,
          authorsMap: res.authorsMap,
          authorInfoMap: res.authorInfoMap,
          likeMetaMap: res.likeMetaMap,
          commentMap: res.commentMap,
          commentCountMap: res.commentCountMap,
        },
      }));
    });
  };

  const visibleBlogs = useMemo(() => {
    let list = [...activeBlogs];

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter((b) => {
        const author = activeAuthorsMap[b.authorId];
        return (
          b.title.toLowerCase().includes(q) ||
          (author?.displayName.toLowerCase().includes(q) ?? false)
        );
      });
    }

    if (sortMode === "newest") {
      list.sort(
        (a, b) =>
          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      );
    } else {
      list.sort((a, b) => {
        const scoreA =
          (activeLikeMetaMap[a.id]?.count ?? 0) * 2 +
          (activeCommentCountMap[a.id] ?? activeCommentMap[a.id]?.length ?? 0);
        const scoreB =
          (activeLikeMetaMap[b.id]?.count ?? 0) * 2 +
          (activeCommentCountMap[b.id] ?? activeCommentMap[b.id]?.length ?? 0);
        return scoreB - scoreA;
      });
    }

    return list;
  }, [
    activeBlogs,
    activeTab,
    searchQuery,
    sortMode,
    activeLikeMetaMap,
    activeCommentMap,
    activeCommentCountMap,
    activeAuthorsMap,
  ]);

  const displayedTotal = activePayload?.blogs.length ?? totalBlogs;

  return (
    <div className="container py-6">
      <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_22rem]">
        <div className="space-y-5 min-w-0">
          <div>
            <h1 className="text-xs font-bold tracking-widest text-foreground uppercase">
              {dict.blog.title}
            </h1>
            <p className="mt-2 text-sm text-muted-foreground leading-relaxed max-w-2xl">
              {dict.blog.description}
            </p>
            <button
              type="button"
              onClick={() => setIsPostModalOpen(true)}
              className="mt-4 inline-flex items-center gap-2 rounded bg-brand px-4 py-1.5 text-sm font-medium text-white hover:bg-brand/90 transition-colors"
            >
              <PenLine className="size-3.5" />
              {dict.blog.postBlog}
            </button>
          </div>

          <div className="flex items-center justify-between">
            <p className="text-sm text-muted-foreground">
              {dict.blog.totalBlogs}{" "}
              <span className="font-semibold text-foreground">
                {displayedTotal.toLocaleString()}
              </span>
            </p>
            <div className="flex items-center gap-1.5">
              <span className="text-sm text-muted-foreground">
                {dict.blog.show}
              </span>
              <button
                type="button"
                onClick={() =>
                  setSortMode((m) => (m === "newest" ? "popular" : "newest"))
                }
                className="inline-flex items-center gap-1 text-sm font-medium text-foreground hover:text-brand transition-colors"
              >
                {sortMode === "newest" ? dict.blog.newest : dict.blog.popular}
                <ChevronDown className="size-4" />
              </button>
            </div>
          </div>

          {activeTab !== "all" && isPending ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="size-5 animate-spin text-muted-foreground" />
            </div>
          ) : visibleBlogs.length > 0 ? (
            <div className="space-y-4">
              {visibleBlogs.map((blog) => {
                const author = activeAuthorsMap[blog.authorId];
                if (!author) return null;
                return (
                  <BlogCard
                    key={blog.id}
                    lang={lang}
                    dict={dict}
                    blog={blog}
                    author={author}
                    likeCount={activeLikeMetaMap[blog.id]?.count ?? 0}
                    liked={activeLikeMetaMap[blog.id]?.liked ?? false}
                    comments={activeCommentMap[blog.id] ?? []}
                    commentCount={activeCommentCountMap[blog.id]}
                    authors={activeAuthorInfoMap}
                    currentUserAvatarSeed={currentUserAvatarSeed}
                  />
                );
              })}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground py-8 text-center">
              {dict.blog.notFound}
            </p>
          )}
        </div>

        <div className="hidden lg:block">
          <div className="sticky top-22">
            <BlogSidebar
              lang={lang}
              dict={dict}
              searchQuery={searchQuery}
              onSearchChange={setSearchQuery}
              activeTab={activeTab}
              onTabChange={handleTabChange}
              recentBlogs={recentBlogs}
            />
          </div>
        </div>
      </div>

      <PostBlogModal
        open={isPostModalOpen}
        onOpenChange={setIsPostModalOpen}
        dict={dict}
      />
    </div>
  );
}

