"use client";

import { useState, useRef, useEffect, useTransition } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import { useRouter } from "next/navigation";
import { Plus, X } from "lucide-react";
import { toast } from "sonner";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import type { Dictionary } from "@/i18n/dictionaries";
import { createBlogAction } from "../actions";

interface PostBlogModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  dict: Dictionary;
}

export function PostBlogModal({
  open,
  onOpenChange,
  dict,
}: PostBlogModalProps) {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!imageFile) return;
    const url = URL.createObjectURL(imageFile);
    setImagePreview(url);
    return () => URL.revokeObjectURL(url);
  }, [imageFile]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) setImageFile(file);
  };

  const removeImage = () => {
    setImageFile(null);
    setImagePreview(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const resetForm = () => {
    setTitle("");
    setDescription("");
    setYoutubeUrl("");
    setImageFile(null);
    setImagePreview(null);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!title.trim() || !description.trim() || isPending) return;

    const formData = new FormData();
    formData.append("title", title.trim());
    formData.append("description", description.trim());
    if (youtubeUrl.trim()) formData.append("youtubeUrl", youtubeUrl.trim());
    if (imageFile) formData.append("imageUrl", imageFile);

    const tags =
      description.match(/#([A-Za-z0-9_]+)/g)?.map((t) => t.slice(1)) ?? [];
    if (tags.length > 0) {
      for (const tag of tags) formData.append("tags[]", tag);
    } else {
      formData.append("tags[]", "general");
    }

    startTransition(async () => {
      const res = await createBlogAction(formData);
      if (!res.success) {
        toast.error(res.message ?? res.error ?? "Failed to post blog");
        return;
      }
      toast.success(res.message ?? "Blog posted successfully");
      resetForm();
      onOpenChange(false);
      router.refresh();
    });
  };

  const handleClose = () => {
    if (isPending) return;
    resetForm();
    onOpenChange(false);
  };

  const isValid = title.trim().length > 0 && description.trim().length > 0;

  const guidelines = [
    dict.blog.modalGuideline1,
    dict.blog.modalGuideline2,
    dict.blog.modalGuideline3,
    dict.blog.modalGuideline4,
  ];

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) handleClose();
      }}
    >
      <DialogContent className="sm:max-w-xl max-h-[90vh] overflow-y-auto scrollbar-hide p-0 bg-white border-none rounded-none">
        <div className="p-8 space-y-6">
          <DialogTitle className="text-center text-lg font-bold tracking-tight text-gray-900">
            {dict.blog.modalTitle}
          </DialogTitle>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-gray-900">
                {dict.blog.modalFieldTitle}
              </label>
              <input
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder={dict.blog.modalFieldTitlePlaceholder}
                maxLength={200}
                className="w-full border border-gray-200 rounded px-3 py-2.5 text-sm outline-none focus:border-brand transition-colors placeholder:text-gray-400"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-gray-900">
                {dict.blog.modalFieldDescription}
              </label>
              <div className="relative">
                <textarea
                  value={description}
                  onChange={(e) =>
                    setDescription(e.target.value.slice(0, 5000))
                  }
                  placeholder={dict.blog.modalFieldDescriptionPlaceholder}
                  rows={6}
                  className="w-full border border-gray-200 rounded px-3 py-2.5 text-sm outline-none focus:border-brand transition-colors resize-none placeholder:text-gray-400"
                />
                <span className="absolute bottom-2.5 right-3 text-[10px] text-gray-400">
                  {description.length.toLocaleString()}/5,000
                </span>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold text-gray-900">
                {dict.blog.modalFieldYoutubeUrl}
              </label>
              <input
                type="text"
                value={youtubeUrl}
                onChange={(e) => setYoutubeUrl(e.target.value)}
                placeholder={dict.blog.modalFieldYoutubeUrlPlaceholder}
                className="w-full border border-gray-200 rounded px-3 py-2.5 text-sm outline-none focus:border-brand transition-colors placeholder:text-gray-400"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-semibold text-gray-900">
                {dict.blog.modalFieldPhoto}
              </label>
              <div>
                {imagePreview ? (
                  <div className="relative w-44 h-44">
                    <Image
                      src={imagePreview}
                      alt="Preview"
                      fill
                      className="object-cover border border-gray-200"
                    />
                    <button
                      type="button"
                      onClick={removeImage}
                      className="absolute -top-2 -right-2 bg-white border border-gray-200 rounded-full p-0.5 hover:bg-gray-100 transition-colors shadow-sm"
                    >
                      <X className="size-3.5 text-gray-600" />
                    </button>
                  </div>
                ) : (
                  <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="w-44 h-44 border border-dashed border-gray-300 flex items-center justify-center hover:border-brand hover:bg-gray-50 transition-colors"
                  >
                    <Plus className="size-7 text-gray-400" />
                  </button>
                )}
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleFileChange}
                  className="hidden"
                />
              </div>
            </div>

            <div className="flex items-center justify-center gap-4 pt-2">
              <button
                type="button"
                onClick={handleClose}
                disabled={isPending}
                className="px-8 py-2.5 border border-gray-300 text-sm font-bold tracking-wide text-gray-700 hover:bg-gray-50 disabled:opacity-50 transition-colors"
              >
                {dict.blog.modalCancel}
              </button>
              <button
                type="submit"
                disabled={!isValid || isPending}
                className="px-8 py-2.5 bg-brand text-white text-sm font-bold tracking-wide hover:bg-brand/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isPending ? dict.blog.modalPosting : dict.blog.modalPostBlog}
              </button>
            </div>

            <div className="pt-1 space-y-2">
              <p className="text-sm text-brand font-medium leading-snug">
                {dict.blog.modalGuidelinesTitle}
              </p>
              <ol className="space-y-1">
                {guidelines.map((line, i) => (
                  <li key={i} className="text-sm text-brand leading-snug">
                    {i + 1}. {line}
                  </li>
                ))}
              </ol>
            </div>
          </form>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { Camera, Heart, MessageCircle, Smile } from "lucide-react";
import { cn } from "@/lib/utils";
import { VerifiedBadge } from "@/components/shared/VerifiedBadge";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import type { User } from "@/lib/types";
import { photoUrl } from "@/lib/image";
import {
  sendWink,
  acceptWink,
  createChatRoom,
  swipeUser,
} from "@/features/member/my-list/action";
import { toast } from "sonner";
import { useRouter } from "next/navigation";

interface Props {
  lang: Locale;
  dict: Dictionary;
  user: User;
}

export function DiscoverProfileCard({ lang, dict, user }: Props) {
  const router = useRouter();
  const [winked, setWinked] = useState(user.isWinked || false);
  const [isSendingWink, setIsSendingWink] = useState(false);
  const [isCreatingChat, setIsCreatingChat] = useState(false);
  const [liked, setLiked] = useState(user.isLiked || false);
  const [isSwiping, setIsSwiping] = useState(false);

  const handleLikeClick = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (isSwiping) return;
    setIsSwiping(true);

    const action = liked ? "dislike" : "like";
    setLiked(!liked);

    try {
      const res = await swipeUser(user.id, action);
      if (res.success) {
        toast.success(res.message || `User ${action}d successfully`);
      } else {
        setLiked(liked);
        toast.error(res.message || "Failed to swipe");
      }
    } catch (error) {
      setLiked(liked);
      toast.error("An error occurred");
    } finally {
      setIsSwiping(false);
    }
  };

  const handleChatClick = async () => {
    try {
      setIsCreatingChat(true);
      const res = await createChatRoom(user.id);
      if (res.success) {
        // Proceed to chat page
        const roomId = res.data?._id || res.data?.id;
        if (roomId) {
          router.push(`/${lang}/chat/${roomId}`);
        } else {
          router.push(`/${lang}/chat`);
        }
      } else {
        console.error("Failed to create chat room", res);
        // Fallback to chat if creation fails (maybe already exists)
        router.push(`/${lang}/chat`);
      }
    } catch (error) {
      console.error(error);
      router.push(`/${lang}/chat`);
    } finally {
      setIsCreatingChat(false);
    }
  };

  const handleWinkClick = async (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (winked) return;
    setIsSendingWink(true);
    try {
      let res;
      if (user.winkId) {
        res = await acceptWink(user.winkId);
      } else {
        res = await sendWink(user.id);
      }

      if (res.success) {
        setWinked(true);
        toast.success(res.message || "Wink sent successfully");
      } else {
        toast.error(res.message || "Failed to send wink");
      }
    } catch (error) {
      toast.error("An error occurred");
    } finally {
      setIsSendingWink(false);
    }
  };
  const photoCount = user.photos.length;

  return (
    <article className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm hover:shadow-md transition-shadow">
      <div className="grid grid-cols-[260px_minmax(0,1fr)] sm:grid-cols-[480px_minmax(0,1fr)]">
        <Link
          href={`/${lang}/my-list/profile/${user.id}`}
          className="relative block overflow-hidden bg-muted min-h-70 lg:min-h-92 2xl:min-h-120 "
        >
          <Image
            src={photoUrl(user.coverSeed, 520, 520)}
            alt={user.displayName}
            fill
            sizes="280px"
            className="object-cover transition-transform hover:scale-105"
            unoptimized
          />
          {photoCount > 1 ? (
            <span className="absolute bottom-2 right-2 inline-flex items-center gap-1 rounded-md bg-black/60 px-2 py-0.5 text-xs text-white">
              <Camera className="size-3" />
              {photoCount}
            </span>
          ) : null}
        </Link>

        <div className="flex flex-col gap-3 lg:gap-5 p-4 sm:p-5 lg:p-6 h-full">
          <div className="space-y-1">
            <div className="flex flex-wrap items-center gap-2">
              <Link
                href={`/${lang}/my-list/profile/${user.id}`}
                className="text-sm lg:text-base font-bold tracking-wide hover:text-brand transition-colors"
              >
                {user.displayName}
              </Link>
              {user.premium ? (
                <span className="rounded-sm border border-border px-1.5 py-0.5 text-[9px] lg:text-[10px] font-semibold tracking-wider text-foreground">
                  {dict.discover.premium}
                </span>
              ) : null}
              {user.verified ? <VerifiedBadge /> : null}
            </div>
            <p className="mt-1 text-xs lg:text-sm leading-relaxed text-muted-foreground">
              {user.age}, {user.city}
              {user.state ? `, ${user.state}` : ""}
              {", "}
              {user.country}
            </p>
            {user.willingToFly ? (
              <p className="text-sm font-medium text-brand">
                {dict.discover.willingToFly}
              </p>
            ) : null}
          </div>

          <div className="space-y-2">
            <h4 className="text-[10px] lg:text-xs font-bold tracking-widest text-foreground uppercase">
              {dict.discover.basicInformation}
            </h4>
            <div className="space-y-1 lg:space-y-1.5">
              {user.ethnicity ? (
                <p className="text-xs lg:text-sm text-brand leading-relaxed">
                  {dict.discover.ethnicity}: {user.ethnicity}
                </p>
              ) : null}
              {user.height ? (
                <p className="text-xs lg:text-sm text-brand leading-relaxed">
                  {dict.discover.height}: {user.height}
                </p>
              ) : null}
              {user.bodyType ? (
                <p className="text-xs lg:text-sm text-brand leading-relaxed">
                  {dict.discover.bodyType}: {user.bodyType}
                </p>
              ) : null}
              {user.livingWith ? (
                <p className="text-xs lg:text-sm text-brand leading-relaxed">
                  {dict.discover.livingWith}: {user.livingWith}
                </p>
              ) : null}
            </div>
          </div>

          {user.headline ? (
            <div className="space-y-2">
              <h4 className="text-[10px] lg:text-xs font-bold tracking-widest text-foreground uppercase">
                {dict.discover.profileHeadline}
              </h4>
              <p className="text-xs lg:text-sm text-brand leading-relaxed lg:leading-loose line-clamp-2">
                {user.headline}
              </p>
            </div>
          ) : null}

          <div className="mt-auto flex items-center gap-6 lg:gap-8 pt-3 lg:pt-5 w-full">
            <button
              type="button"
              aria-label="Wink"
              onClick={handleWinkClick}
              disabled={isSendingWink || winked}
              className={`transition-colors disabled:opacity-50 ${winked ? "text-brand" : "text-muted-foreground hover:text-brand"}`}
            >
              <Smile 
                className={cn(
                  "size-5 lg:size-6 transition-transform", 
                  winked && "fill-current stroke-card scale-110"
                )} 
              />
            </button>
            <button
              type="button"
              aria-label="Message"
              onClick={handleChatClick}
              disabled={isCreatingChat}
              className="text-muted-foreground hover:text-brand transition-colors disabled:opacity-50"
            >
              <MessageCircle className="size-5 lg:size-6" />
            </button>
            <button
              type="button"
              aria-label="Like"
              onClick={handleLikeClick}
              disabled={isSwiping}
              className={`transition-colors disabled:opacity-50 ${liked ? "text-red-500" : "text-muted-foreground hover:text-brand"}`}
            >
              <Heart
                className={cn("size-5 lg:size-6", liked && "fill-current")}
              />
            </button>
          </div>
        </div>
      </div>
    </article>
  );
}

"use client";

import { useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { Heart, MessageCircle } from "lucide-react";
import { avatarUrl } from "@/lib/image";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { Dictionary } from "@/i18n/dictionaries";
import type { DiseaseCategory, DiseasePost, DiseasePostComment } from "./types";
import { diseaseOptions } from "./data";

export const brandButtonClass =
  "bg-[#429CA8] text-white hover:bg-[#388994] shadow-[0_16px_35px_rgba(66,156,168,0.24)]";

export type AnonymousProfile = {
  name: string;
  username?: string;
  image: string;
};

export const anonymousProfiles: AnonymousProfile[] = [
  { name: "Anonymous Hope", image: avatarUrl("anonymous-hope", 96) },
  { name: "Anonymous Care", image: avatarUrl("anonymous-care", 96) },
  { name: "Anonymous Calm", image: avatarUrl("anonymous-calm", 96) },
  { name: "Anonymous Light", image: avatarUrl("anonymous-light", 96) },
];

export function getAuthorProfile(authorId: string) {
  if (authorId === "u_lucas")
    return { name: "Lucas", username: "lucas", image: avatarUrl(authorId, 96) };
  if (authorId === "u_maya")
    return { name: "Maya", username: "maya", image: avatarUrl(authorId, 96) };
  if (authorId === "u_aurora")
    return {
      name: "Aurora",
      username: "aurora",
      image: avatarUrl(authorId, 96),
    };
  if (authorId === "u_camila")
    return {
      name: "Camila",
      username: "camila",
      image: avatarUrl(authorId, 96),
    };
  if (authorId === "u_sofia")
    return { name: "Sofia", username: "sofia", image: avatarUrl(authorId, 96) };
  if (authorId === "u_beatriz")
    return {
      name: "Beatriz",
      username: "beatriz",
      image: avatarUrl(authorId, 96),
    };
  if (authorId === "u_helena")
    return {
      name: "Helena",
      username: "helena",
      image: avatarUrl(authorId, 96),
    };
  if (authorId === "u_olivia")
    return {
      name: "Olivia",
      username: "olivia",
      image: avatarUrl(authorId, 96),
    };
  if (authorId === "u_pedro")
    return { name: "Pedro", username: "pedro", image: avatarUrl(authorId, 96) };
  return {
    name: "Community member",
    username: "member",
    image: avatarUrl(authorId, 96),
  };
}

export function getAnonymousProfile(index = 0) {
  return anonymousProfiles[index % anonymousProfiles.length];
}

export function formatDate(date: string, lang: string) {
  return new Intl.DateTimeFormat(lang === "pt" ? "pt-BR" : "en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(new Date(date));
}

export function PostHeader({
  post,
  lang,
  href,
  onOpen,
  onLike,
  isLiked,
  onCommentSubmit,
  onCommentLike,
  dict,
}: {
  post: DiseasePost;
  lang: string;
  href: string;
  onOpen: () => void;
  onLike?: (e: React.MouseEvent) => void;
  isLiked?: boolean;
  onCommentSubmit?: (text: string, anonymous: boolean) => void;
  onCommentLike?: (commentId: string) => void;
  dict: Dictionary;
}) {
  const author = post.anonymous
    ? getAnonymousProfile(0)
    : getAuthorProfile(post.authorId);

  return (
    <div className="group relative w-full text-left rounded-[2rem] border border-white/70 bg-white/95 p-5 shadow-[0_20px_60px_rgba(15,23,42,0.06)] transition-all hover:-translate-y-0.5 hover:shadow-[0_24px_80px_rgba(15,23,42,0.1)]">
      <Link
        href={href}
        onClick={onOpen}
        className="absolute inset-0 z-0 rounded-[2rem]"
        aria-label="View post details"
      />

      <div className="relative z-10 flex items-start gap-4 pointer-events-none">
        <Image
          src={author.image}
          alt={author.name}
          width={52}
          height={52}
          className="size-13 shrink-0 rounded-full object-cover ring-2 ring-white shadow-sm"
          unoptimized
        />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <div className="flex items-center gap-2">
              <p className="font-semibold text-slate-950">
                {post.anonymous ? dict.diseaseQa.anonymousAuthor : author.name}
              </p>
              <span className="text-xs text-muted-foreground">
                • {formatDate(post.createdAt, lang)}
              </span>
            </div>
            <span className="rounded-full bg-[#429CA8]/10 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-[0.25em] text-[#2b7e87]">
              {post.disease}
            </span>
          </div>

          <h3 className="mt-3 text-xl font-semibold tracking-tight text-slate-950 group-hover:text-[#429CA8] transition-colors pointer-events-auto w-fit">
            <Link href={href} onClick={onOpen}>
              {post.title}
            </Link>
          </h3>
          <p className="mt-2 line-clamp-3 text-sm leading-7 text-slate-600 pointer-events-auto">
            <Link href={href} onClick={onOpen}>
              {post.body}
            </Link>
          </p>

          {/* Interaction Bar */}
          <div className="mt-5 flex items-center gap-6 border-t border-slate-100/80 pt-4 pointer-events-auto">
            <button
              type="button"
              onClick={onLike}
              className={`flex items-center gap-2 text-sm font-medium transition-colors group/like ${isLiked ? "text-rose-500" : "text-slate-500 hover:text-rose-500"}`}
            >
              <div
                className={`flex size-9 items-center justify-center rounded-full transition-colors ${isLiked ? "bg-rose-50" : "bg-slate-50 group-hover/like:bg-rose-50"}`}
              >
                <Heart
                  className={`size-4.5 transition-colors ${isLiked ? "fill-rose-500 text-rose-500" : "text-slate-400 group-hover/like:text-rose-500"}`}
                />
              </div>
              <span>{post.likesCount > 0 ? post.likesCount : "Like"}</span>
            </button>

            <Link
              href={href}
              onClick={onOpen}
              className="flex items-center gap-2 text-sm font-medium text-slate-500 hover:text-[#429CA8] transition-colors group/comment"
            >
              <div
                className={`flex size-9 items-center justify-center rounded-full transition-colors ${post.commentsCount > 0 ? "bg-[#429CA8]/10" : "bg-slate-50 group-hover/comment:bg-[#429CA8]/10"}`}
              >
                <MessageCircle
                  className={`size-4.5 transition-colors ${post.commentsCount > 0 ? "text-[#429CA8] fill-[#429CA8]/20" : "text-slate-400 group-hover/comment:text-[#429CA8]"}`}
                />
              </div>
              <span>
                {post.commentsCount > 0 ? post.commentsCount : "Comment"}
              </span>
            </Link>
          </div>

          {/* Comments Section */}
          {onCommentSubmit && (
            <div className="mt-5 space-y-4 border-t border-slate-100/80 pt-4 pointer-events-auto">
              {post.comments.slice(0, 2).map((comment) => (
                <CommentCard
                  key={comment.id}
                  comment={comment}
                  anonymous={comment.anonymous}
                  dict={dict}
                  onLike={() => onCommentLike?.(comment.id)}
                />
              ))}

              {post.comments.length > 2 && (
                <Link
                  href={href}
                  onClick={onOpen}
                  className="inline-block text-sm font-medium text-[#2b7e87] hover:underline"
                >
                  {dict.diseaseQa.viewAllComments.replace(
                    "{{count}}",
                    post.comments.length.toString(),
                  )}
                </Link>
              )}

              <div className="mt-2">
                <CommentComposer
                  dict={dict}
                  onSubmit={(payload) =>
                    onCommentSubmit(payload.text, payload.anonymous)
                  }
                />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export function ReactionStats({
  likes,
  comments,
}: {
  likes: number;
  comments: number;
}) {
  return (
    <div className="flex items-center gap-3 text-sm text-muted-foreground">
      <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-3 py-1.5">
        <Heart className="size-3.5" />
        {likes}
      </span>
      <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-3 py-1.5">
        <MessageCircle className="size-3.5" />
        {comments}
      </span>
    </div>
  );
}

export function AddDiseasePostDialog({
  open,
  onOpenChange,
  dict,
  onCreate,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  dict: Dictionary;
  onCreate: (payload: {
    title: string;
    body: string;
    disease: DiseaseCategory;
    anonymous: boolean;
  }) => void;
}) {
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [disease, setDisease] = useState<DiseaseCategory>("Herpes");
  const [anonymous, setAnonymous] = useState(true);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] min-w-xl overflow-hidden p-0">
        <div className="max-h-[90vh] overflow-y-auto p-6">
          <DialogHeader>
            <DialogTitle className="text-2xl">
              {dict.diseaseQa.createPostTitle}
            </DialogTitle>
            <DialogDescription>
              {dict.diseaseQa.createPostDescription}
            </DialogDescription>
          </DialogHeader>

          <div className="mt-6 grid gap-4">
            <Input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder={dict.diseaseQa.postTitlePlaceholder}
              className="min-h-10"
            />
            <Select
              value={disease}
              onValueChange={(value) => setDisease(value as DiseaseCategory)}
            >
              <SelectTrigger className="min-h-10 w-full">
                <SelectValue placeholder={dict.diseaseQa.diseasePlaceholder} />
              </SelectTrigger>
              <SelectContent>
                {diseaseOptions.map((option) => (
                  <SelectItem key={option} value={option}>
                    {option}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Textarea
              value={body}
              onChange={(e) => setBody(e.target.value)}
              placeholder={dict.diseaseQa.postBodyPlaceholder}
              className="min-h-36"
            />

            <label className="flex items-center justify-between rounded-[1.25rem] border border-[#429CA8]/12 bg-[#429CA8]/6 px-4 py-3">
              <div>
                <p className="font-medium text-slate-900">
                  {dict.diseaseQa.postAnonymousLabel}
                </p>
                <p className="text-sm text-muted-foreground">
                  {dict.diseaseQa.postAnonymousHelp}
                </p>
              </div>
              <input
                type="checkbox"
                checked={anonymous}
                onChange={(e) => setAnonymous(e.target.checked)}
                className="size-5 accent-[#429CA8]"
              />
            </label>
          </div>

          <DialogFooter className="mt-6">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              {dict.common.back}
            </Button>
            <Button
              className={brandButtonClass}
              onClick={() => {
                if (!title.trim() || !body.trim()) return;
                onCreate({
                  title: title.trim(),
                  body: body.trim(),
                  disease,
                  anonymous,
                });
                setTitle("");
                setBody("");
                setAnonymous(true);
                setDisease("Herpes");
                onOpenChange(false);
              }}
            >
              {dict.diseaseQa.createPostSubmit}
            </Button>
          </DialogFooter>
        </div>
      </DialogContent>
    </Dialog>
  );
}

export function CommentComposer({
  dict,
  onSubmit,
}: {
  dict: Dictionary;
  onSubmit: (payload: { text: string; anonymous: boolean }) => void;
}) {
  const [text, setText] = useState("");
  const [anonymous, setAnonymous] = useState(true);

  return (
    <form
      className="rounded-[1.5rem] border border-[#429CA8]/12 bg-[#429CA8]/6 p-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (!text.trim()) return;
        onSubmit({ text: text.trim(), anonymous });
        setText("");
        setAnonymous(true);
      }}
    >
      <Textarea
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder={dict.diseaseQa.commentPlaceholder}
        className="min-h-28 bg-white"
      />
      <div className="mt-3 flex flex-wrap items-center justify-between gap-3">
        <label className="inline-flex items-center gap-2 text-sm text-slate-700">
          <input
            type="checkbox"
            checked={anonymous}
            onChange={(e) => setAnonymous(e.target.checked)}
            className="size-4 accent-[#429CA8]"
          />
          {dict.diseaseQa.commentAnonymousLabel}
        </label>
        <Button type="submit" className={brandButtonClass}>
          {dict.diseaseQa.commentSubmit}
        </Button>
      </div>
    </form>
  );
}

export function CommentCard({
  comment,
  anonymous,
  dict,
  onLike,
}: {
  comment: DiseasePostComment;
  anonymous: boolean;
  dict: Dictionary;
  onLike: () => void;
}) {
  const author = anonymous
    ? getAnonymousProfile(1)
    : getAuthorProfile(comment.authorId);
  return (
    <div className="rounded-[1.35rem] border border-white/70 bg-white p-4 shadow-[0_14px_40px_rgba(15,23,42,0.05)]">
      <div className="flex items-start gap-3">
        <Image
          src={author.image}
          alt={author.name}
          width={40}
          height={40}
          className="size-10 rounded-full object-cover ring-2 ring-white"
          unoptimized
        />
        <div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2">
            <p className="font-semibold text-slate-950">
              {anonymous ? dict.diseaseQa.anonymousAuthor : author.name}
            </p>
            <span className="text-xs text-muted-foreground">
              {anonymous
                ? dict.diseaseQa.anonymousLabel
                : `@${author.username}`}
            </span>
          </div>
          <p className="mt-2 text-sm leading-6 text-slate-600">
            {comment.text}
          </p>
        </div>
      </div>
      <div className="mt-3 flex items-center justify-between">
        <button
          type="button"
          onClick={onLike}
          className="inline-flex items-center gap-1.5 text-sm font-medium text-[#2b7e87]"
        >
          <Heart className="size-4" />
          {comment.likesCount}
        </button>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import { CalendarDays, Clock3, Heart, MapPin, MessageCircle, Smile } from "lucide-react";
import { useRouter } from "next/navigation";
import BackButton from "@/components/shared/BackButton";
import { EventFormDialog } from "./EventFormDialog";
import type { MemberEvent } from "./types";

function formatDate(value: string, withTime = false) {
  if (!value) return "—";
  const date = new Date(value);
  return new Intl.DateTimeFormat("en-US", {
    month: "long",
    day: "numeric",
    year: "numeric",
    ...(withTime
      ? {
          hour: "numeric",
          minute: "2-digit",
        }
      : {}),
  }).format(date);
}

interface EventDetailsClientProps {
  event: MemberEvent;
  isOwner: boolean;
}

export function EventDetailsClient({
  event,
  isOwner,
}: EventDetailsClientProps) {
  const router = useRouter();
  const [active, setActive] = useState("join-event");

  useEffect(() => {
    const handler = () => {
      const ids = ["join-event", "details", "private-note"];
      let current = ids[0];
      for (const id of ids) {
        const el = document.getElementById(id);
        if (el && el.getBoundingClientRect().top <= 140) current = id;
      }
      setActive(current);
    };

    window.addEventListener("scroll", handler, { passive: true });
    handler();
    return () => window.removeEventListener("scroll", handler);
  }, []);

  const ownerName = event.owner?.name || "Event host";
  const ownerImage = event.owner?.profile || "/image20.png";
  const ownerMeta = [
    event.owner?.nationality || event.owner?.country,
    event.owner?.state,
  ]
    .filter(Boolean)
    .join(", ");

  const navItems = [
    { id: "join-event", label: `JOIN ${ownerName.toUpperCase()}'S EVENT` },
    { id: "details", label: "EVENT DETAILS" },
    { id: "private-note", label: "ADD A PRIVATE NOTE" },
  ];

  return (
    <div className="container py-5">
      <div className="grid gap-8 lg:grid-cols-[14rem_minmax(0,1fr)]">
        <div>
          <div className="lg:sticky lg:top-22">
            <BackButton />

            <aside className="space-y-5">
              <div className="overflow-hidden rounded-xl bg-muted">
                <Image
                  src={ownerImage}
                  alt={ownerName}
                  width={480}
                  height={600}
                  className="aspect-4/5 w-full object-cover"
                  unoptimized
                />
              </div>

              <div className="flex items-center gap-5 px-1 text-muted-foreground">
                <button type="button" aria-label="Wink" className="hover:text-brand transition-colors">
                  <Smile className="size-5" />
                </button>
                <button type="button" aria-label="Like" className="hover:text-brand transition-colors">
                  <Heart className="size-5" />
                </button>
                <button type="button" aria-label="Message" className="hover:text-brand transition-colors">
                  <MessageCircle className="size-5" />
                </button>
              </div>

              <nav className="space-y-3 px-1 pt-2 text-xs font-semibold tracking-wider">
                {navItems.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() =>
                      document
                        .getElementById(item.id)
                        ?.scrollIntoView({ behavior: "smooth", block: "start" })
                    }
                    className={
                      active === item.id
                        ? "block text-left text-foreground underline underline-offset-4"
                        : "block text-left text-muted-foreground transition-colors hover:text-foreground"
                    }
                  >
                    {item.label}
                  </button>
                ))}
              </nav>
            </aside>
          </div>
        </div>

        <div className="space-y-8">
          <header className="flex items-start justify-between gap-3">
            <div className="space-y-1">
              <h1 className="text-base font-semibold tracking-wider">{ownerName}</h1>
              {ownerMeta ? (
                <p className="text-sm text-muted-foreground">{ownerMeta}</p>
              ) : null}
            </div>
            {isOwner ? (
              <EventFormDialog
                mode="edit"
                event={event}
                triggerLabel="Edit event"
                onSuccess={() => router.refresh()}
              />
            ) : null}
          </header>

          <section id="join-event" className="space-y-4 rounded-2xl border border-border bg-card p-5 scroll-mt-24">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <h2 className="text-lg font-semibold uppercase tracking-wide">
                Join {ownerName.toUpperCase()}'s Event
              </h2>
              <div className="flex flex-wrap gap-2">
                <span className="rounded-full bg-muted px-3 py-1 text-xs font-medium text-muted-foreground">
                  {event.visibility}
                </span>
                <span className="rounded-full bg-brand/10 px-3 py-1 text-xs font-medium text-brand">
                  {event.status}
                </span>
              </div>
            </div>

            <div className="space-y-3">
              <h3 className="text-2xl font-semibold text-foreground">{event.eventName}</h3>
              <p className="text-sm text-muted-foreground">{event.type}</p>
            </div>

            <div className="grid gap-4 text-sm text-foreground/90 md:grid-cols-2">
              <div className="flex items-start gap-2">
                <CalendarDays className="mt-0.5 size-4 text-brand" />
                <div>
                  <p className="font-medium">Date</p>
                  <p>
                    {formatDate(event.startDate)} - {formatDate(event.endDate)}
                  </p>
                </div>
              </div>
              <div className="flex items-start gap-2">
                <Clock3 className="mt-0.5 size-4 text-brand" />
                <div>
                  <p className="font-medium">Start time</p>
                  <p>{formatDate(event.startTime, true)}</p>
                </div>
              </div>
              <div className="flex items-start gap-2 md:col-span-2">
                <MapPin className="mt-0.5 size-4 text-brand" />
                <div>
                  <p className="font-medium">Location</p>
                  <p>{ownerMeta || "Location not provided"}</p>
                </div>
              </div>
            </div>
          </section>

          <section id="details" className="space-y-3 scroll-mt-24">
            <h2 className="text-sm font-semibold uppercase tracking-wider text-foreground">
              Event Details
            </h2>
            <div className="rounded-2xl border border-border bg-card p-5">
              <p className="whitespace-pre-line text-sm leading-7 text-muted-foreground">
                {event.details}
              </p>

              <div className="mt-6 grid gap-3 text-sm text-muted-foreground sm:grid-cols-2">
                <p>Created: {formatDate(event.createdAt, true)}</p>
                <p>Updated: {formatDate(event.updatedAt, true)}</p>
                <p>Invited guests: {event.guests.length}</p>
              </div>
            </div>
          </section>

          <section id="private-note" className="space-y-3 scroll-mt-24">
            <h2 className="text-sm font-semibold uppercase tracking-wider text-foreground">
              Add A Private Note
            </h2>
            <textarea
              rows={4}
              placeholder="Write a private note about this event..."
              className="w-full rounded-xl border border-border bg-card px-4 py-3 text-sm outline-none transition-colors focus:border-brand"
            />
          </section>
        </div>
      </div>
    </div>
  );
}

