"use client";

import { useEffect, useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { ChevronLeft, ChevronRight, Heart, RotateCcw, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { VerifiedBadge } from "@/components/shared/VerifiedBadge";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import type { User } from "@/lib/types";
import { photoUrl } from "@/lib/image";

interface FlameCardProps {
  lang: Locale;
  dict: Dictionary;
  user: User;
  canUndo: boolean;
  isPremium: boolean;
  disabled?: boolean;
  onPass: () => void;
  onLike: () => void;
  onUndo: () => void;
}

function formatHeight(height: string) {
  if (!height) return "";
  return /^\d+(\.\d+)?$/.test(height) ? `${height} cm` : height;
}

function formatWeight(weight?: string) {
  if (!weight) return "";
  return /^\d+(\.\d+)?$/.test(weight) ? `${weight} kg` : weight;
}

function formatRelationStatus(status: string) {
  if (!status) return "";
  return status.charAt(0) + status.slice(1).toLowerCase();
}

function formatEducation(education?: string) {
  if (!education) return "";
  return education.charAt(0) + education.slice(1).toLowerCase();
}

export function FlameCard({
  lang,
  user,
  canUndo,
  isPremium,
  disabled = false,
  onPass,
  onLike,
  onUndo,
}: FlameCardProps) {
  const [photoIdx, setPhotoIdx] = useState(0);

  useEffect(() => {
    setPhotoIdx(0);
  }, [user.id]);

  const photos = user.photos.length > 0 ? user.photos : [user.coverSeed];
  const photoCount = photos.length;
  const currentSeed = photos[photoIdx] ?? user.coverSeed;
  const profileHref = `/${lang}/profile/${encodeURIComponent(user.username)}`;
  const nameLabel =
    user.age > 0 ? `${user.displayName}, ${user.age}` : user.displayName;

  const prevPhoto = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setPhotoIdx((i) => (i - 1 + photoCount) % photoCount);
  };

  const nextPhoto = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setPhotoIdx((i) => (i + 1) % photoCount);
  };

  return (
    <TooltipProvider>
      <article className="overflow-hidden rounded-xl border border-border bg-card">
        <div className="grid gap-0 md:grid-cols-[minmax(0,520px)_minmax(0,1fr)] min-h-[calc(100vh-160px)]">
          <div className="group relative aspect-square w-full bg-muted md:aspect-auto md:h-full">
            <Link
              href={profileHref}
              className="relative block h-full w-full"
              aria-label={`Open ${user.displayName}'s profile`}
            >
              <Image
                src={photoUrl(currentSeed, 800, 920)}
                alt={user.displayName}
                fill
                sizes="(max-width: 768px) 100vw, 520px"
                className="object-cover"
                priority
                unoptimized
              />
            </Link>

            {photoCount > 1 ? (
              <>
                <span className="pointer-events-none absolute left-3 top-3 rounded-md bg-black/60 px-2 py-0.5 text-xs font-medium text-white">
                  {photoIdx + 1} / {photoCount}
                </span>
                <button
                  type="button"
                  onClick={prevPhoto}
                  aria-label="Previous photo"
                  className="absolute left-2 top-1/2 inline-flex size-9 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md bg-black/40 text-white opacity-0 transition-opacity hover:bg-black/60 group-hover:opacity-100 focus-visible:opacity-100"
                >
                  <ChevronLeft className="size-5" />
                </button>
                <button
                  type="button"
                  onClick={nextPhoto}
                  aria-label="Next photo"
                  className="absolute right-2 top-1/2 inline-flex size-9 -translate-y-1/2 cursor-pointer items-center justify-center rounded-md bg-black/40 text-white opacity-0 transition-opacity hover:bg-black/60 group-hover:opacity-100 focus-visible:opacity-100"
                >
                  <ChevronRight className="size-5" />
                </button>
              </>
            ) : null}

            <div className="absolute bottom-4 left-1/2 flex -translate-x-1/2 items-center gap-3">
              {canUndo ? (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      onClick={onUndo}
                      disabled={!isPremium || disabled}
                      aria-label={
                        isPremium ? "Undo last pass" : "Undo (premium required)"
                      }
                      className={cn(
                        "inline-flex size-12 cursor-pointer items-center justify-center rounded-full bg-white shadow-md transition-transform",
                        isPremium && !disabled
                          ? "text-foreground hover:scale-105"
                          : "cursor-not-allowed text-muted-foreground opacity-60",
                      )}
                    >
                      <RotateCcw className="size-5" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>
                    {isPremium ? "Undo last pass" : "Subscribe to use Undo"}
                  </TooltipContent>
                </Tooltip>
              ) : null}

              <Tooltip>
                <TooltipTrigger asChild>
                  <button
                    type="button"
                    onClick={onPass}
                    disabled={disabled}
                    aria-label="Pass"
                    className="inline-flex size-12 cursor-pointer items-center justify-center rounded-full bg-white text-foreground shadow-md transition-transform hover:scale-105 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    <X className="size-5" />
                  </button>
                </TooltipTrigger>
                <TooltipContent>Pass</TooltipContent>
              </Tooltip>

              <Tooltip>
                <TooltipTrigger asChild>
                  <button
                    type="button"
                    onClick={onLike}
                    disabled={disabled}
                    aria-label="Like"
                    className="inline-flex size-12 cursor-pointer items-center justify-center rounded-full bg-white text-brand shadow-md transition-transform hover:scale-105 disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    <Heart className="size-5 fill-brand" />
                  </button>
                </TooltipTrigger>
                <TooltipContent>Like</TooltipContent>
              </Tooltip>
            </div>
          </div>

          <div className="flex flex-col gap-8 p-8 justify-start">
            <div className="space-y-2">
              <div className="flex flex-wrap items-center gap-2.5">
                <Link
                  href={profileHref}
                  className="text-2xl font-extrabold tracking-wide hover:text-brand transition-colors"
                >
                  {nameLabel}
                </Link>
                {user.premium ? (
                  <span className="rounded-sm border border-border px-1.5 py-0.5 text-[10px] font-semibold tracking-wider text-foreground">
                    PREMIUM
                  </span>
                ) : null}
                {user.verified ? <VerifiedBadge /> : null}
              </div>
              {user.country ? (
                <p className="text-base text-muted-foreground">{user.country}</p>
              ) : null}
              {user.willingToFly ? (
                <p className="text-base font-semibold text-brand">
                  Willing to fly to meet
                </p>
              ) : null}
            </div>

            <div className="space-y-3">
              <h4 className="text-sm font-bold uppercase tracking-widest text-foreground/80">
                More About Me
              </h4>
              <dl className="space-y-2 text-base">
                <Row
                  label="Relationship status"
                  value={formatRelationStatus(user.relationshipStatus)}
                />
                <Row label="Height" value={formatHeight(user.height)} />
                <Row label="Weight" value={formatWeight(user.weight)} />
                <Row label="Education" value={formatEducation(user.education)} />
              </dl>
            </div>

            {user.headline || user.bio ? (
              <div className="space-y-2">
                <h4 className="text-sm font-bold uppercase tracking-widest text-foreground/80">
                  Profile Headline
                </h4>
                <p className="text-base leading-relaxed text-foreground">
                  {user.headline || user.bio}
                </p>
              </div>
            ) : null}
          </div>
        </div>
      </article>
    </TooltipProvider>
  );
}

function Row({ label, value }: { label: string; value: string }) {
  if (!value) return null;
  return (
    <div className="text-foreground">
      <span className="font-semibold text-foreground/90">{label}:</span> {value}
    </div>
  );
}

