"use client";

import { useEffect, useState, useTransition } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import Link from "next/link";
import { ThumbsUp, MessageCircle, Send } from "lucide-react";
import { toast } from "sonner";
import {
  createBlogCommentAction,
  toggleBlogLikeAction,
} from "@/features/member/blog/actions";
import {
  createPostCommentAction,
  togglePostLikeAction,
} from "@/features/member/home/action";
import { avatarUrl } from "@/lib/image";
import { cn } from "@/lib/utils";
import type { Comment } from "@/lib/types";

interface PostActionsProps {
  kind: "video" | "moment" | "blog";
  postId: string;
  initialLikeCount: number;
  initialLiked: boolean;
  initialComments: Comment[];
  initialCommentCount?: number;
  authors: Record<string, { displayName: string; avatarSeed: string }>;
  currentUserAvatarSeed: string;
  commentPlaceholder?: string;
}

export function PostActions({
  kind,
  postId,
  initialLikeCount,
  initialLiked,
  initialComments,
  initialCommentCount,
  authors: initialAuthors,
  currentUserAvatarSeed,
  commentPlaceholder = "Write a comment...",
  lang = "en",
}: PostActionsProps & { lang?: string }) {
  const [likes, setLikes] = useState({
    count: initialLikeCount,
    liked: initialLiked,
  });
  const [comments, setComments] = useState<Comment[]>(initialComments);
  const [authors, setAuthors] =
    useState<Record<string, { displayName: string; avatarSeed: string }>>(
      initialAuthors,
    );
  const [showComments, setShowComments] = useState(initialComments.length > 0);
  const [text, setText] = useState("");
  const [isPending, startTransition] = useTransition();

  useEffect(() => {
    setLikes({ count: initialLikeCount, liked: initialLiked });
    setComments(initialComments);
    setAuthors(initialAuthors);
    if (initialComments.length > 0) {
      setShowComments(true);
    }
  }, [initialLikeCount, initialLiked, initialComments, initialAuthors]);

  const commentCount = Math.max(initialCommentCount ?? 0, comments.length);

  const onLike = () => {
    const prev = likes;
    const nextLiked = !prev.liked;
    const nextCount = nextLiked
      ? prev.count + 1
      : Math.max(0, prev.count - 1);

    setLikes({ count: nextCount, liked: nextLiked });

    startTransition(async () => {
      if (kind === "blog") {
        const res = await toggleBlogLikeAction(postId);
        if (!res.success) {
          setLikes(prev);
          toast.error(res.message ?? "Failed to update blog like");
          return;
        }

        setLikes({
          liked:
            typeof res.data?.liked === "boolean"
              ? res.data.liked
              : typeof res.data?.isLiked === "boolean"
                ? res.data.isLiked
                : nextLiked,
          count:
            typeof res.data?.likeCount === "number"
              ? res.data.likeCount
              : typeof res.data?.totalLikes === "number"
                ? res.data.totalLikes
                : nextCount,
        });
        return;
      }

      const res = await togglePostLikeAction(postId);
      if (!res.success) {
        setLikes(prev);
        toast.error(res.message ?? "Failed to update like");
        return;
      }

      setLikes({
        liked:
          typeof res.data?.liked === "boolean"
            ? res.data.liked
            : typeof res.data?.isLiked === "boolean"
              ? res.data.isLiked
              : nextLiked,
        count:
          typeof res.data?.likeCount === "number"
            ? res.data.likeCount
            : nextCount,
      });
    });
  };

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = text.trim();
    if (!trimmed) return;
    setText("");
    setShowComments(true);
    startTransition(async () => {
      const res =
        kind === "blog"
          ? await createBlogCommentAction(postId, trimmed)
          : await createPostCommentAction(postId, trimmed);

      if (!res.success) {
        toast.error(res.message ?? "Failed to post comment");
        return;
      }
      setComments(res.comments);
      if (res.authors) {
        setAuthors((prev) => ({ ...prev, ...res.authors }));
      }
    });
  };

  return (
    <>
      <div className="flex items-center justify-end gap-4 border-t border-border px-4 py-2">
        <button
          type="button"
          onClick={onLike}
          disabled={isPending}
          className={cn(
            "inline-flex items-center gap-1.5 text-sm transition-colors",
            likes.liked
              ? "text-brand"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          <ThumbsUp className={cn("size-4", likes.liked ? "fill-brand" : "")} />
          {likes.count > 0 ? likes.count : ""}
        </button>
        <button
          type="button"
          onClick={() => setShowComments((s) => !s)}
          className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          <MessageCircle className="size-4" />
          {commentCount > 0 ? commentCount : ""}
        </button>
      </div>

      {showComments ? (
        <div className="border-t border-border px-4 py-3 space-y-3 bg-muted/30">
          {comments.map((c) => {
            const author = authors[c.authorId];
            return (
              <div key={c.id} className="flex gap-2 text-sm">
                <Link
                  href={`/${lang}/my-list/profile/${c.authorId}`}
                  className="shrink-0"
                >
                  <Image
                    src={avatarUrl(author?.avatarSeed ?? c.authorId, 48)}
                    alt={author?.displayName ?? ""}
                    width={28}
                    height={28}
                    className="size-7 rounded-full object-cover"
                    unoptimized
                  />
                </Link>
                <div className="min-w-0">
                  <Link
                    href={`/${lang}/my-list/profile/${c.authorId}`}
                  >
                    <p className="text-xs font-semibold hover:text-brand transition-colors">
                      {author?.displayName ?? "USER"}
                    </p>
                  </Link>
                  <p className="text-sm text-foreground">{c.text}</p>
                </div>
              </div>
            );
          })}
          <form onSubmit={onSubmit} className="flex items-center gap-2 pt-1">
            <Image
              src={avatarUrl(currentUserAvatarSeed, 48)}
              alt=""
              width={28}
              height={28}
              className="size-7 shrink-0 rounded-full object-cover"
              unoptimized
            />
            <input
              type="text"
              value={text}
              onChange={(e) => setText(e.target.value)}
              placeholder={commentPlaceholder}
              className="flex-1 rounded-full border border-border bg-background px-3 py-1.5 text-sm outline-none focus:border-brand"
            />
            <button
              type="submit"
              disabled={!text.trim() || isPending}
              aria-label="Send"
              className="rounded-full p-2 text-brand hover:bg-brand-soft disabled:opacity-40 disabled:hover:bg-transparent"
            >
              <Send className="size-4" />
            </button>
          </form>
        </div>
      ) : null}
    </>
  );
}

