"use client";

import { useEffect, useMemo, useRef, useState, useTransition } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import { useRouter } from "next/navigation";
import { Pencil, Plus, X } from "lucide-react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import type { Dictionary } from "@/i18n/dictionaries";
import { cn } from "@/lib/utils";
import { createPostAction, updatePostAction } from "../action";

interface CreatePostModalProps {
  dict: Dictionary;
  trigger?: React.ReactNode;
  mode?: "create" | "edit";
  postId?: string;
  initialDescription?: string;
  initialImageUrls?: string[];
}

const EMPTY_IMAGES: string[] = [];

const HASHTAGS = [
  "Pet",
  "Music",
  "Fitness",
  "Travel",
  "Food",
  "Happy",
  "Friends",
  "Selfie",
  "Fashion",
  "Love",
  "Question",
  "Event",
  "Study",
  "Stdtest",
  "Mentalhealth",
  "Story",
  "Relationship",
  "Endherpes",
  "Support",
  "Health",
  "Lifestlye",
  "Herpesdating",
  "Herpescure",
  "Herpesawareness",
  "Hsv",
];

export function CreatePostModal({
  dict,
  trigger,
  mode = "create",
  postId,
  initialDescription = "",
  initialImageUrls = EMPTY_IMAGES,
}: CreatePostModalProps) {
  const router = useRouter();
  const [text, setText] = useState(initialDescription);
  const [files, setFiles] = useState<File[]>([]);
  const [filePreviews, setFilePreviews] = useState<string[]>([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isPending, startTransition] = useTransition();
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const urls = files.map((file) => URL.createObjectURL(file));
    setFilePreviews(urls);
    return () => {
      urls.forEach((url) => URL.revokeObjectURL(url));
    };
  }, [files]);

  const previews = useMemo(
    () => [...initialImageUrls, ...filePreviews],
    [initialImageUrls, filePreviews],
  );

  const resetForm = () => {
    setText(initialDescription);
    setFiles([]);
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const handleOpenChange = (open: boolean) => {
    setIsOpen(open);
    if (open) {
      setText(initialDescription);
      setFiles([]);
      if (fileInputRef.current) fileInputRef.current.value = "";
    } else {
      resetForm();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const nextFiles = Array.from(e.target.files);
    setFiles((prev) => [...prev, ...nextFiles].slice(0, 9));
  };

  const removeFile = (index: number) => {
    const existingCount = initialImageUrls.length;
    if (index < existingCount) return;
    const fileIndex = index - existingCount;
    setFiles((prev) => prev.filter((_, i) => i !== fileIndex));
  };

  const toggleHashtag = (tag: string) => {
    const hashtag = `#${tag}`;
    if (text.includes(hashtag)) {
      setText((prev) =>
        prev.replace(new RegExp(`${hashtag}\\s?`, "g"), "").trim(),
      );
    } else {
      setText((prev) => `${prev}${prev ? " " : ""}${hashtag}`.trim());
    }
  };

  const handleSubmit = () => {
    if (isPending) return;
    if (!text.trim() && files.length === 0 && initialImageUrls.length === 0) {
      return;
    }

    const formData = new FormData();
    formData.append("description", text.trim());
    formData.append("type", "IMAGE");

    for (const file of files) {
      formData.append("content", file);
    }

    startTransition(async () => {
      const res =
        mode === "edit" && postId
          ? await updatePostAction(postId, formData)
          : await createPostAction(formData);

      if (!res.success) {
        toast.error(res.message ?? res.error ?? "Failed to save post");
        return;
      }

      toast.success(
        res.message ??
          (mode === "edit"
            ? "Post updated successfully"
            : "Post created successfully"),
      );
      setIsOpen(false);
      resetForm();
      router.refresh();
    });
  };

  const canPost =
    (text.trim().length > 0 ||
      files.length > 0 ||
      initialImageUrls.length > 0) &&
    !isPending;

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogTrigger asChild>
        {trigger ?? (
          <button
            type="button"
            className="flex w-full items-center gap-2 rounded-md border border-border bg-background px-4 py-4 text-left text-sm text-muted-foreground hover:border-brand hover:text-foreground transition-colors"
          >
            <Pencil className="size-4 shrink-0" />
            <span>{dict.myHome.composerPlaceholder}</span>
          </button>
        )}
      </DialogTrigger>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto scrollbar-hide p-0 bg-white border-none rounded-none">
        <div className="relative p-8 space-y-8">
          <DialogTitle className="text-center text-2xl font-bold tracking-tight text-gray-900">
            {mode === "edit" ? "Edit Moment" : "Add Moment"}
          </DialogTitle>

          <div className="space-y-4">
            <label className="text-sm font-bold text-gray-900">
              Add photos ({Math.min(previews.length, 9)}/9)*
            </label>
            <div className="grid grid-cols-3 gap-4">
              {previews.map((src, i) => (
                <div
                  key={`${src}-${i}`}
                  className="group relative aspect-3/4 overflow-hidden bg-gray-100"
                >
                  <Image
                    src={src}
                    alt={`Preview ${i}`}
                    fill
                    className="object-cover"
                    unoptimized
                  />
                  {i >= initialImageUrls.length ? (
                    <button
                      type="button"
                      onClick={() => removeFile(i)}
                      className="absolute top-2 right-2 p-1 bg-black/50 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      <X className="size-4" />
                    </button>
                  ) : null}
                </div>
              ))}

              {previews.length < 9 ? (
                <button
                  type="button"
                  onClick={() => fileInputRef.current?.click()}
                  className="flex aspect-3/4 items-center justify-center border-2 border-dashed border-gray-300 hover:border-black transition-colors"
                >
                  <Plus className="size-10 text-gray-400" />
                </button>
              ) : null}
            </div>
            <input
              type="file"
              ref={fileInputRef}
              accept="image/*"
              multiple
              className="hidden"
              onChange={handleFileChange}
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-900">
              Description
            </label>
            <div className="relative">
              <textarea
                value={text}
                onChange={(e) => setText(e.target.value.slice(0, 2000))}
                rows={6}
                placeholder="e.g. Amar sonar bangla"
                className="w-full border border-gray-200 p-4 text-sm focus:outline-none focus:border-gray-400 resize-none"
              />
              <div className="absolute bottom-4 right-4 text-[10px] font-medium text-gray-400">
                {text.length.toLocaleString("en-US")}/2,000
              </div>
            </div>
          </div>

          <div className="flex flex-wrap gap-2">
            {HASHTAGS.map((tag) => {
              const isActive = text.includes(`#${tag}`);
              return (
                <button
                  key={tag}
                  type="button"
                  onClick={() => toggleHashtag(tag)}
                  className={cn(
                    "px-3 py-1.5 border text-xs font-medium transition-colors",
                    isActive
                      ? "border-brand bg-brand text-white"
                      : "border-gray-200 text-gray-600 hover:border-gray-400",
                  )}
                >
                  #{tag}
                </button>
              );
            })}
          </div>

          <button
            type="button"
            disabled={!canPost}
            onClick={handleSubmit}
            className="w-full py-3 bg-brand text-white text-xs font-bold tracking-[0.2em] uppercase transition-colors hover:bg-brand-hover disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isPending
              ? mode === "edit"
                ? "Saving..."
                : "Posting..."
              : mode === "edit"
                ? "SAVE"
                : "POST"}
          </button>

          <div className="space-y-2 pt-4">
            <p className="text-sm font-bold text-gray-900">Note:</p>
            <p className="text-xs text-gray-600 leading-relaxed">
              Photos that are lewd, offensive, nude, racist, or featuring
              children are prohibited, as are any other photos or videos that
              are prohibited by law, protected by a copyright, or that violate
              our{" "}
              <a href="#" className="text-blue-600 underline">
                Service Agreement
              </a>
              .
            </p>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState, useRef } from "react";
import { X, Camera, Trash2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { reportPost } from "../action";

interface ReportContentModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  reasonsTitle?: string;
  detailsTitle?: string;
  detailsPlaceholder?: string;
  evidenceTitle?: string;
  evidenceNote?: string;
  addLabel?: string;
  postId?: string;
}

const REPORT_REASONS = [
  {
    label: "Using an AI-generated photo or video",
    value: "usingAiGeneratedContent",
  },
  {
    label: "Contains contact information",
    value: "containsContactInformation",
  },
  {
    label: "Inappropriate or obscene content",
    value: "inappropriateOrObsceneContent",
  },
  {
    label: "Photo impersonating another individual",
    value: "photoImpersonatingAnotherIndividual",
  },
  { label: "Photo of a child", value: "photoOfAChild" },
  { label: "Other", value: "other" },
];

export function ReportContentModal({
  open,
  onOpenChange,
  title = "REPORT THIS PHOTO OR VIDEO",
  reasonsTitle = "Reasons for reporting*",
  detailsTitle = "More details (optional)",
  detailsPlaceholder = "Your report is confidential. Please provide more details to help our review.",
  evidenceTitle = "Upload evidence (optional)",
  evidenceNote = "(Upload up to 4 photos or screenshots to help us better understand the issue.)",
  addLabel = "ADD",
  postId,
}: ReportContentModalProps) {
  const [reason, setReason] = useState<string>("");
  const [details, setDetails] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const newFiles = Array.from(e.target.files);
      setFiles((prev) => [...prev, ...newFiles].slice(0, 4));
    }
  };

  const removeFile = (index: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!postId) {
      toast.error("User or Post ID is missing");
      return;
    }
    if (!reason) {
      toast.error("Please select a reason");
      return;
    }

    setIsSubmitting(true);
    try {
      const formData = new FormData();
      formData.append("postId", postId);
      formData.append("reason", reason);
      if (details) formData.append("description", details);
      files.forEach((file) => {
        formData.append("image", file);
      });

      const res = await reportPost(formData);
      if (res.success) {
        toast.success(res.message || "Report submitted successfully");
        setReason("");
        setDetails("");
        setFiles([]);
        onOpenChange(false);
      } else {
        toast.error(res.message || "Failed to submit report");
      }
    } catch (error) {
      toast.error("An error occurred");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-xl p-0 rounded-none sm:rounded-none border-none max-h-[calc(100vh-10rem)] overflow-auto scrollbar-hide">
        <form onSubmit={handleSubmit} className="bg-white p-6 sm:p-10 relative">
          <DialogHeader className="mb-8 items-center">
            <DialogTitle className="text-xl font-bold tracking-tight">
              {title}
            </DialogTitle>
          </DialogHeader>

          <div className="space-y-8">
            <div className="space-y-4">
              <h3 className="text-base font-bold">{reasonsTitle}</h3>
              <RadioGroup
                value={reason}
                onValueChange={setReason}
                className="space-y-4"
              >
                {REPORT_REASONS.map((r) => (
                  <div key={r.value} className="flex items-center space-x-3">
                    <RadioGroupItem
                      value={r.value}
                      id={r.value}
                      className="size-5"
                    />
                    <Label
                      htmlFor={r.value}
                      className="text-base font-normal cursor-pointer leading-tight"
                    >
                      {r.label}
                    </Label>
                  </div>
                ))}
              </RadioGroup>
            </div>

            <div className="space-y-3">
              <h3 className="text-base font-bold">{detailsTitle}</h3>
              <div className="relative">
                <Textarea
                  placeholder={detailsPlaceholder}
                  className="min-h-35 resize-none border-gray-300 bg-white p-4 text-base focus:border-brand focus:ring-1 focus:ring-brand"
                  maxLength={5000}
                  value={details}
                  onChange={(e) => setDetails(e.target.value)}
                />
                <div className="mt-1 text-right text-sm text-muted-foreground">
                  {details.length}/5,000
                </div>
              </div>
            </div>

            <div className="space-y-3 pb-4">
              <h3 className="text-base font-bold">{evidenceTitle}</h3>
              <p className="text-sm text-muted-foreground">{evidenceNote}</p>
              <div className="mt-4 flex flex-wrap gap-4">
                {files.map((file, i) => (
                  <div
                    key={i}
                    className="relative size-24 border border-border"
                  >
                    <img
                      src={URL.createObjectURL(file)}
                      alt="Evidence"
                      className="size-full object-cover"
                    />
                    <button
                      type="button"
                      onClick={() => removeFile(i)}
                      className="absolute -right-2 -top-2 rounded-full bg-destructive p-1 text-white hover:bg-destructive/90"
                    >
                      <Trash2 className="size-3" />
                    </button>
                  </div>
                ))}
                {files.length < 4 && (
                  <>
                    <input
                      type="file"
                      ref={fileInputRef}
                      className="hidden"
                      multiple
                      accept="image/*"
                      onChange={handleFileChange}
                    />
                    <button
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      className="flex size-24 flex-col items-center justify-center gap-2 border border-dashed border-gray-300 bg-gray-50 hover:bg-gray-100 transition-colors"
                    >
                      <Camera className="size-6 text-muted-foreground" />
                      <span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">
                        {addLabel}
                      </span>
                    </button>
                  </>
                )}
              </div>
            </div>

            <div className="pt-6">
              <Button
                type="submit"
                className="w-full text-base font-bold py-6 bg-brand hover:bg-brand-hover text-white"
                disabled={isSubmitting || !reason}
              >
                {isSubmitting ? "SUBMITTING..." : "SUBMIT REPORT"}
              </Button>
            </div>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

