"use client";

import { useEffect, useState } from "react";
import { Pencil } from "lucide-react";
import { cn } from "@/lib/utils";

interface EditableTextProps {
  id?: string;
  title: string;
  placeholder?: string;
  value: string;
  onSave: (next: string) => void;
  maxLength?: number;
}

export function EditableText({
  id,
  title,
  placeholder,
  value,
  onSave,
  maxLength = 2000,
}: EditableTextProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);

  useEffect(() => {
    if (!editing) setDraft(value);
  }, [editing, value]);

  const handleSave = () => {
    onSave(draft.trim());
    setEditing(false);
  };

  const handleCancel = () => {
    setDraft(value);
    setEditing(false);
  };

  return (
    <section id={id} className="space-y-2 py-5">
      <div className="flex items-start justify-between gap-3">
        <h3 className="text-sm font-bold text-foreground">{title}</h3>
        {!editing ? (
          <button
            type="button"
            onClick={() => setEditing(true)}
            aria-label={`Edit ${title}`}
            className="text-muted-foreground hover:text-brand transition-colors cursor-pointer"
          >
            <Pencil className="size-4" />
          </button>
        ) : null}
      </div>

      {!editing ? (
        <p
          className={cn(
            "text-sm leading-relaxed",
            value ? "text-foreground" : "text-muted-foreground italic",
          )}
        >
          {value || placeholder || "Add details about yourself."}
        </p>
      ) : (
        <div className="space-y-2">
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value.slice(0, maxLength))}
            placeholder={placeholder}
            rows={4}
            className="w-full rounded-md border border-border bg-background p-3 text-sm outline-none focus:border-brand"
          />
          <div className="flex items-center justify-between text-xs text-muted-foreground">
            <span>
              {draft.length}/{maxLength.toLocaleString()}
            </span>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={handleCancel}
                className="rounded-md border border-input bg-background px-3 py-1.5 text-xs font-medium hover:bg-muted transition-colors cursor-pointer"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={handleSave}
                className="rounded-md bg-brand px-3 py-1.5 text-xs font-medium text-white hover:bg-brand-hover transition-colors cursor-pointer"
              >
                Save
              </button>
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { ImageWithFallback as Image } from "@/components/shared/ImageWithFallback";
import { getPrivateAlbum } from "../action";
import { Loader2, Lock } from "lucide-react";
import { getImageUrl } from "@/helpers/getImageUrl";

export function PrivateAlbumBlock() {
  const [albumData, setAlbumData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchAlbum = async () => {
      try {
        const res = await getPrivateAlbum();
        if (res.success && res.data) {
          setAlbumData(res.data);
        }
      } catch (error) {
        console.error("Failed to load private album", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAlbum();
  }, []);

  if (isLoading) {
    return (
      <div className="flex justify-center py-8">
        <Loader2 className="w-6 h-6 animate-spin text-brand" />
      </div>
    );
  }

  if (!albumData) {
    return null;
  }

  return (
    <section className="space-y-4">
      <div className="flex items-center gap-2">
        <Lock className="w-5 h-5 text-brand" />
        <h3 className="text-lg font-bold">My Private Album</h3>
      </div>
      <p className="text-sm text-muted-foreground">
        These photos and media are protected and only visible to members you
        grant access to.
      </p>

      {albumData.images && albumData.images.length > 0 && (
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">Private Images</h4>
          <div className="grid grid-cols-3 gap-3">
            {albumData.images.map((img: string, idx: number) => (
              <div
                key={idx}
                className="relative aspect-square overflow-hidden bg-muted rounded-md"
              >
                <Image
                  src={getImageUrl(img) || ""}
                  alt={`Private image ${idx + 1}`}
                  fill
                  className="object-cover"
                  unoptimized
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {albumData.protectedImages && albumData.protectedImages.length > 0 && (
        <div className="space-y-2 mt-4">
          <h4 className="text-sm font-semibold">Protected Images</h4>
          <div className="grid grid-cols-3 gap-3">
            {albumData.protectedImages.map((img: string, idx: number) => (
              <div
                key={idx}
                className="relative aspect-square overflow-hidden bg-muted rounded-md"
              >
                <Image
                  src={getImageUrl(img) || ""}
                  alt={`Protected image ${idx + 1}`}
                  fill
                  className="object-cover"
                  unoptimized
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {albumData.media && albumData.media.length > 0 && (
        <div className="space-y-2 mt-4">
          <h4 className="text-sm font-semibold">Private Media</h4>
          <div className="grid grid-cols-2 gap-3">
            {albumData.media.map((vid: string, idx: number) => (
              <div
                key={idx}
                className="relative aspect-video overflow-hidden bg-black rounded-md flex items-center justify-center"
              >
                <video
                  src={getImageUrl(vid) || ""}
                  controls
                  className="max-w-full max-h-full"
                />
              </div>
            ))}
          </div>
        </div>
      )}
    </section>
  );
}

