"use client";

import { useState, useEffect } from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import {
  Shield,
  Bell,
  User,
  EyeOff,
  Ban,
  MessageSquare,
  RefreshCw,
} from "lucide-react";
import { cn } from "@/lib/utils";
import PrivacyTab from "./tabs/PrivacyTab";
import NotificationsTab from "./tabs/NotificationsTab";
import MyAccountTab from "./tabs/MyAccountTab";
import HiddenMembersTab from "./tabs/HiddenMembersTab";
import DeletedMembersTab from "./tabs/DeletedMembersTab";
import AutoReplyTab from "./tabs/AutoReplyTab";
import ResetPassesTab from "./tabs/ResetPassesTab";

interface SettingsPageFeatureProps {
  lang: string;
  dict: any;
}

export default function SettingsPageFeature({
  lang,
  dict,
}: SettingsPageFeatureProps) {
  const searchParams = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();

  const initialTab = searchParams.get("tab") || "myAccount";
  const [activeTab, setActiveTab] = useState(initialTab);
  const t = dict.settings;

  useEffect(() => {
    const tab = searchParams.get("tab");
    if (tab && tab !== activeTab) {
      setActiveTab(tab);
    }
  }, [searchParams]);

  const handleTabChange = (id: string) => {
    setActiveTab(id);
    const newParams = new URLSearchParams(searchParams.toString());
    newParams.set("tab", id);
    router.replace(`${pathname}?${newParams.toString()}`);
  };

  const menuItems = [
    { id: "group1", type: "heading", label: t.sections.account },
    // { id: "privacy", type: "item", label: t.tabs.privacy, icon: Shield },
    // {
    //   id: "notifications",
    //   type: "item",
    //   label: t.tabs.notifications,
    //   icon: Bell,
    // },
    { id: "myAccount", type: "item", label: t.tabs.myAccount, icon: User },
    {
      id: "hiddenMembers",
      type: "item",
      label: t.tabs.hiddenMembers,
      icon: EyeOff,
    },
    {
      id: "deletedMembers",
      type: "item",
      label: t.tabs.deletedMembers,
      icon: Ban,
    },
    // { id: "group2", type: "heading", label: t.sections.customization },
    // {
    //   id: "autoReply",
    //   type: "item",
    //   label: t.tabs.autoReply,
    //   icon: MessageSquare,
    // },
    { id: "group3", type: "heading", label: t.sections.general },
    {
      id: "resetPasses",
      type: "item",
      label: t.tabs.resetPasses,
      icon: RefreshCw,
    },
  ];

  const renderTabContent = () => {
    switch (activeTab) {
      case "privacy":
        return <PrivacyTab t={t} />;
      case "notifications":
        return <NotificationsTab t={t} />;
      case "myAccount":
        return <MyAccountTab t={t} />;
      case "hiddenMembers":
        return <HiddenMembersTab t={t} />;
      case "deletedMembers":
        return <DeletedMembersTab t={t} />;
      case "autoReply":
        return <AutoReplyTab t={t} />;
      case "resetPasses":
        return <ResetPassesTab t={t} />;
      default:
        return <MyAccountTab t={t} />;
    }
  };

  return (
    <div className="min-h-screen bg-neutral-50/60  text-neutral-900 antialiased">
      <div className="container py-8 ">
        <h1 className="text-3xl font-bold tracking-tight mb-8 bg-linear-to-r from-neutral-900 to-neutral-600 bg-clip-text text-transparent">
          {t.title}
        </h1>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start relative">
          {/* Side Navigation */}
          <nav className="lg:col-span-4 bg-white/80  backdrop-blur-md p-4 rounded-2xl border border-neutral-200/60 shadow-sm space-y-1 lg:sticky lg:top-20">
            {menuItems.map((item) => {
              if (item.type === "heading") {
                return (
                  <h3
                    key={item.id}
                    className="text-xs font-semibold uppercase tracking-wider text-neutral-400 pt-4 pb-2 px-3 first:pt-0"
                  >
                    {item.label}
                  </h3>
                );
              }

              const Icon = item.icon!;
              const isActive = activeTab === item.id;

              return (
                <button
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={cn(
                    "w-full flex items-center gap-3 px-3 py-3 text-sm font-medium rounded-xl transition-all duration-200 ease-out group relative",
                    isActive
                      ? "text-[#429CA8] bg-[#429CA8]/8 "
                      : "text-neutral-600  hover:bg-neutral-100/80 ",
                  )}
                >
                  {isActive && (
                    <span className="absolute left-0 top-3 bottom-3 w-1 bg-[#429CA8] rounded-full" />
                  )}
                  <Icon
                    className={cn(
                      "w-5 h-5 transition-transform duration-200 group-hover:scale-105",
                      isActive ? "text-[#429CA8]" : "text-neutral-400 ",
                    )}
                  />
                  {item.label}
                </button>
              );
            })}
          </nav>

          {/* Settings Tab Work Area */}
          <main className="lg:col-span-8 bg-white  rounded-2xl border border-neutral-200/60 shadow-sm overflow-hidden p-6 sm:p-8 min-h-150 transition-all duration-300">
            {renderTabContent()}
          </main>
        </div>
      </div>
    </div>
  );
}

// @/components/settings/tabs/AutoReplyTab.tsx
"use client";

import React, { useState } from "react";
import { Plus, CheckCircle2, Circle, X, Check, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

export default function AutoReplyTab({ t }: { t: any }) {
  // Array of reply options
  const [templates, setTemplates] = useState<string[]>([
    "Thanks for your message! I'm currently offline but will reply when I'm back.",
    "Thanks for reaching out! I'm taking a short break and will respond soon.",
  ]);

  const [selectedReply, setSelectedReply] = useState<number>(0);

  // UI Flow States
  const [isCreating, setIsCreating] = useState<boolean>(false);
  const [newReplyText, setNewReplyText] = useState<string>("");
  const [isSaving, setIsSaving] = useState<boolean>(false);

  const MAX_CHARS = 160; // Standard premium length constraint

  const handleCreateReply = async () => {
    if (!newReplyText.trim()) return;

    setIsSaving(true);

    // Simulate database/API mutation latency
    await new Promise((resolve) => setTimeout(resolve, 800));

    const updatedTemplates = [...templates, newReplyText.trim()];
    setTemplates(updatedTemplates);

    // Auto-select the newly minted custom reply card
    setSelectedReply(updatedTemplates.length - 1);

    // Clean up input contexts
    setNewReplyText("");
    setIsCreating(false);
    setIsSaving(false);
  };

  return (
    <div className="space-y-6 animate-fade-in text-neutral-900">
      <div>
        <h2 className="text-xl font-bold tracking-tight mb-1">
          {t.tabs.autoReply}
        </h2>
        <p className="text-xs text-neutral-400 leading-normal max-w-xl">
          {t.autoReply.desc}
        </p>
      </div>

      {/* Target Container List */}
      <div className="space-y-3">
        {templates.map((text, idx) => {
          const isSelected = selectedReply === idx;
          return (
            <div
              key={idx}
              onClick={() => setSelectedReply(idx)}
              className={cn(
                "p-4 rounded-xl border-2 cursor-pointer transition-all flex items-start gap-3.5 group relative",
                isSelected
                  ? "border-[#429CA8] bg-[#429CA8]/5"
                  : "border-neutral-100 bg-white hover:border-neutral-200",
              )}
            >
              <div className="mt-0.5 shrink-0 transition-transform duration-200 group-hover:scale-105">
                {isSelected ? (
                  <CheckCircle2 className="w-5 h-5 text-[#429CA8] fill-[#429CA8]/10" />
                ) : (
                  <Circle className="w-5 h-5 text-neutral-300" />
                )}
              </div>
              <p
                className={cn(
                  "text-sm leading-relaxed font-medium pr-4",
                  isSelected
                    ? "text-neutral-900 font-semibold"
                    : "text-neutral-500",
                )}
              >
                {text}
              </p>
            </div>
          );
        })}
      </div>

      {/* Expandable Creation Composer Sheet */}
      {isCreating ? (
        <div className="p-4 rounded-xl border border-neutral-200 bg-neutral-50/50 space-y-3 animate-fade-in">
          <div className="relative">
            <Textarea
              value={newReplyText}
              onChange={(e) =>
                setNewReplyText(e.target.value.slice(0, MAX_CHARS))
              }
              placeholder={
                t.autoReply.placeholder ||
                "Type your automated matching message here..."
              }
              disabled={isSaving}
              className="w-full bg-white border-neutral-200 rounded-xl resize-none min-h-20 p-3 text-sm focus-visible:ring-[#429CA8] focus-visible:ring-offset-0 transition-all placeholder:text-neutral-400 text-neutral-800"
            />
            <span className="absolute bottom-2.5 right-3 text-[10px] font-medium text-neutral-400 bg-white/80 px-1.5 py-0.5 rounded-md backdrop-blur-sm">
              {newReplyText.length} / {MAX_CHARS}
            </span>
          </div>

          <div className="flex items-center justify-end gap-2">
            <Button
              size="sm"
              variant="outline"
              disabled={isSaving}
              onClick={() => {
                setIsCreating(false);
                setNewReplyText("");
              }}
              className="h-9 px-3 rounded-xl border-neutral-200 text-neutral-500 hover:bg-neutral-100 font-medium text-xs flex items-center gap-1.5"
            >
              <X className="w-3.5 h-3.5" />
              {t.common?.cancel || "Cancel"}
            </Button>

            <Button
              size="sm"
              disabled={!newReplyText.trim() || isSaving}
              onClick={handleCreateReply}
              className="h-9 px-4 bg-[#429CA8] hover:bg-[#357d87] text-white rounded-xl font-semibold text-xs flex items-center gap-1.5 disabled:opacity-50"
            >
              {isSaving ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Check className="w-3.5 h-3.5" />
              )}
              {t.common?.save || "Save Template"}
            </Button>
          </div>
        </div>
      ) : (
        /* Action trigger to append standard collection elements */
        <Button
          variant="outline"
          onClick={() => setIsCreating(true)}
          className="w-full py-5 border-dashed border-2 bg-white border-neutral-200 hover:border-[#429CA8]/60 hover:bg-[#429CA8]/5 text-neutral-600 hover:text-[#429CA8] transition-all rounded-xl text-sm font-semibold flex items-center justify-center gap-2 shadow-sm"
        >
          <Plus className="w-4 h-4" />
          {t.autoReply.addCustom}
        </Button>
      )}
    </div>
  );
}

