              <img
                src={avatarUrl(story.user.profileImage, 120)}
                alt={story.user.name}
                className="size-12 rounded-full object-cover ring-2 ring-white"
              />
            </Link>
            <div className="min-w-0">
              <Link
                href={`/${lang}/profile/${story.user.username}`}
                className="block truncate font-semibold text-slate-900 hover:text-[#429CA8]"
              >
                {story.user.name}
              </Link>
              <p className="text-xs text-muted-foreground">
                {formatDate(story.createdAt, lang)}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-1">
            {story.user.id === currentUser.id ? (
              <AddSuccessStoryDialog
                mode="edit"
                story={story}
                title="Edit success story"
                description="Update your story and optionally upload new media."
                userAvatar={avatarUrl(currentUser.avatarSeed, 96)}
                trigger={
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-sm"
                    className="rounded-full"
                    aria-label="Edit story"
                  >
                    <Pencil className="size-4" />
                  </Button>
                }
              />
            ) : null}

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon-sm" className="rounded-full">
                  <MoreHorizontal className="size-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem asChild>
                  <Link href={storyHref}>Open details</Link>
                </DropdownMenuItem>
                <DropdownMenuItem
                  onSelect={() =>
                    toast.message("Report sent", {
                      description:
                        "Thanks for helping keep the community safe.",
                    })
                  }
                >
                  Report
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>

        <div className="mt-4 flex flex-wrap items-center gap-2">
          <Badge
            className={cn(
              "rounded-full px-3 py-1 text-[11px] font-semibold tracking-wide ring-1",
              meta.className,
            )}
          >
            {meta.label}
          </Badge>
          {mediaCount > 0 ? (
            <Badge
              variant="outline"
              className="rounded-full border-dashed px-3 py-1 text-[11px] font-semibold"
            >
              {mediaCount} media
            </Badge>
          ) : null}
          <Badge
            variant="outline"
            className="rounded-full border-[#429CA8]/20 px-3 py-1 text-[11px] font-semibold text-[#2b7e87]"
          >
            {story.relationshipStatus}
          </Badge>
        </div>

        <div className="mt-4">
          <Link href={storyHref} className="group block">
            <h2 className="text-2xl font-semibold tracking-tight text-slate-950 group-hover:text-[#429CA8]">
              {story.title}
            </h2>
            <p className="mt-2 text-sm leading-7 text-slate-600 line-clamp-3">
              {story.story}
            </p>
          </Link>
        </div>
      </div>

      <div className="p-5 sm:p-6">
        <StoryMediaStrip media={story.media} storyHref={storyHref} />

        <div className="mt-5 flex gap-3 items-center">
          <Button
            type="button"
            variant="outline"
            className={cn(
              " justify-start gap-2 rounded-[1.25rem] border-[#429CA8]/18 px-4 py-6",
              liked
                ? "bg-[#429CA8] text-[#429CA8]! hover:bg-[#388994]"
                : "text-slate-900",
            )}
            onClick={() => void onLike(story.id)}
          >
            <Heart className={cn("size-4", liked && "fill-current")} />
            <span>{story.likesCount}</span>
          </Button>

          <Button
            type="button"
            variant="outline"
            className=" justify-start gap-2 rounded-[1.25rem] border-[#429CA8]/18 px-4 py-6 text-slate-900"
            onClick={() => {
              const input = document.getElementById(
                commentInputId,
              ) as HTMLTextAreaElement | null;
              input?.focus();
              input?.scrollIntoView({ behavior: "smooth", block: "center" });
            }}
          >
            <MessageCircle className="size-4" />
            <span>{story.commentsCount}</span>
          </Button>

          <Button
            variant="ghost"
            className="rounded-full sm:col-span-2"
            onClick={() =>
              toast.message(dict.successStories.share, {
                description: "Sharing can be wired to your real flow next.",
              })
            }
          >
            <Share2 className="size-4" />
            {dict.successStories.share}
          </Button>
        </div>

        <form
          className="mt-5 flex items-start gap-3 rounded-[1.5rem] border border-[#429CA8]/12 bg-[#429CA8]/6 p-4"
          onSubmit={async (e) => {
            e.preventDefault();
            if (!comment.trim()) return;
            await onComment(story.id, comment.trim());
            setComment("");
          }}
        >
          <Image
            src={avatarUrl(currentUser.avatarSeed, 80)}
            alt=""
            height={80}
            width={80}
            className="size-9 rounded-full object-cover ring-2 ring-white"
          />
          <div className="min-w-0 flex-1">
            <textarea
              id={commentInputId}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder={dict.successStories.commentPlaceholder}
              className="min-h-20 w-full resize-none rounded-2xl border border-[#429CA8]/15 bg-white px-4 py-3 text-sm outline-none ring-0 placeholder:text-slate-400 focus:border-[#429CA8]"
            />
            <div className="mt-3 flex items-center justify-between gap-3">
              <p className="text-xs text-muted-foreground">
                {dict.successStories.commentHint}
              </p>
              <Button type="submit" className={brandButtonClass}>
                {dict.successStories.comment}
              </Button>
            </div>
          </div>
        </form>

        <div className="mt-5">
          <div className="mb-3 flex items-center justify-between">
            <p className="text-sm font-semibold text-slate-900">
              Recent comments
            </p>
            <p className="text-xs text-muted-foreground">
              {previewComments.length} shown
            </p>
          </div>
          <StoryComments comments={previewComments} compact />
        </div>
      </div>
    </article>
  );
}

"use client";

import { useEffect, useMemo, useState, useTransition } from "react";
import Link from "next/link";
import { ArrowLeft, ChevronDown, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { Locale } from "@/i18n/config";
import type { Dictionary } from "@/i18n/dictionaries";
import { avatarUrl } from "@/lib/image";
import { AddSuccessStoryDialog } from "./AddSuccessStoryDialog";
import { StoryCard } from "./StoryCard";
import { countMedia } from "./shared";
import { sortOptions } from "../../../lib/mock/success-stories-mock";
import type { SuccessStory, SuccessStoriesSortKey } from "./types";
import { toast } from "sonner";
import {
  createSuccessStoryCommentAction,
  toggleSuccessStoryLikeAction,
} from "./action";

const sortKeyMap: Record<string, SuccessStoriesSortKey> = {
  Newest: "newest",
  "Photos & Videos": "media",
  "Most Popular": "popular",
  Dating: "dating",
  Engaged: "engaged",
  Other: "other",
  "My Post": "mine",
};

function FeedFilters({
  sortKey,
  setSortKey,
  isPending,
  totalStories,
  totalMedia,
}: {
  sortKey: SuccessStoriesSortKey;
  setSortKey: (value: SuccessStoriesSortKey) => void;
  isPending: boolean;
  totalStories: number;
  totalMedia: number;
}) {
  return (
    <aside className="grid gap-4 rounded-[2rem] border border-white/70 bg-slate-950 p-6 text-white shadow-[0_24px_80px_rgba(15,23,42,0.16)]">
      <p className="text-xs font-semibold uppercase tracking-[0.35em] text-white/65">
        Feed filters
      </p>
      <div className="flex flex-wrap gap-2">
        {sortOptions.map((option) => {
          const key = sortKeyMap[option];
          const active = sortKey === key;

          return (
            <button
              key={option}
              type="button"
              onClick={() => setSortKey(key)}
              className={[
                "rounded-full border px-4 py-2 text-sm transition-all",
                active
                  ? "border-white bg-white text-slate-950 shadow-lg"
                  : "border-white/15 bg-white/5 text-white/78 hover:bg-white/10",
              ].join(" ")}
            >
              {option}
            </button>
          );
        })}
      </div>
      <div className="grid gap-3 rounded-2xl bg-white/8 p-4 ring-1 ring-white/10 sm:grid-cols-3">
        <div>
          <p className="text-2xl font-semibold">{totalStories}</p>
          <p className="text-xs text-white/65">Stories</p>
        </div>
        <div>
          <p className="text-2xl font-semibold">{totalMedia}</p>
          <p className="text-xs text-white/65">Media</p>
        </div>
        <div>
          <p className="text-2xl font-semibold">
            {isPending ? "Live" : "Ready"}
          </p>
          <p className="text-xs text-white/65">Sort updates</p>
        </div>
      </div>
    </aside>
  );
}

export function SuccessStoriesPageClient({
  lang,
  dict,
  currentUser,
  initialStories,
}: {
  lang: Locale;
  dict: Dictionary;
  currentUser: { id: string; username: string; avatarSeed: string };
  initialStories: SuccessStory[];
}) {
  const [stories, setStories] = useState(initialStories);
  const [sortKey, setSortKey] = useState<SuccessStoriesSortKey>("newest");
  const [isPending, startTransition] = useTransition();
  const [likedStoryIds, setLikedStoryIds] = useState<string[]>(() =>
    initialStories.filter((story) => story.isLiked).map((story) => story.id),
  );

  useEffect(() => {
    setStories(initialStories);
    setLikedStoryIds(
      initialStories.filter((story) => story.isLiked).map((story) => story.id),
    );
  }, [initialStories]);

  const visibleStories = useMemo(() => {
    const list = [...stories];
    return list.sort((a, b) => {
      if (sortKey === "newest")
        return +new Date(b.createdAt) - +new Date(a.createdAt);
      if (sortKey === "popular") return b.likesCount - a.likesCount;
      if (sortKey === "media") return countMedia(b) - countMedia(a);
      if (sortKey === "dating")
        return (
          Number(b.relationshipStatus === "DATING") -
          Number(a.relationshipStatus === "DATING")
        );
      if (sortKey === "engaged")
        return (
          Number(b.relationshipStatus === "ENGAGED") -
          Number(a.relationshipStatus === "ENGAGED")
        );
      if (sortKey === "other")
        return (
          Number(b.relationshipStatus === "OTHER") -
          Number(a.relationshipStatus === "OTHER")
        );
      if (sortKey === "mine")
        return (
          Number(b.user.username === currentUser.username) -
          Number(a.user.username === currentUser.username)
        );
      return 0;
    });
  }, [stories, sortKey, currentUser.username]);

  const handleLike = async (storyId: string) => {
    const wasLiked = likedStoryIds.includes(storyId);
    const nextLiked = !wasLiked;
    const updateLike = (liked: boolean, count?: number) => {
      setLikedStoryIds((previous) =>
        liked
          ? Array.from(new Set([...previous, storyId]))
          : previous.filter((id) => id !== storyId),
      );
      setStories((current) =>
        current.map((story) =>
          story.id === storyId
            ? {
                ...story,
                isLiked: liked,
                likesCount:
                  count ??
                  Math.max(story.likesCount + (liked ? 1 : -1), 0),
              }
            : story,
        ),
      );
    };

    updateLike(nextLiked);
    const result = await toggleSuccessStoryLikeAction(storyId);
    if (!result.success) {
      updateLike(wasLiked);
      toast.error(result.message ?? "Failed to update like");
      return;
    }

    const liked =
      typeof result.data?.liked === "boolean"
        ? result.data.liked
        : typeof result.data?.isLiked === "boolean"
          ? result.data.isLiked
          : nextLiked;
    const count =
      typeof result.data?.totalLikes === "number"
        ? result.data.totalLikes
        : result.data?.likesCount;
    if (liked !== nextLiked || typeof count === "number") {
      updateLike(liked, count);
    }
  };

  const handleComment = async (storyId: string, text: string) => {
    const result = await createSuccessStoryCommentAction(storyId, text);
    if (!result.success) {
      toast.error(result.message ?? "Failed to post comment");
      return;
    }

    setStories((previous) =>
      previous.map((story) =>
        story.id === storyId
          ? {
              ...story,
              commentsCount: result.comments.length,
              comments: result.comments,
            }
          : story,
      ),
    );
    toast.success(result.message ?? "Comment posted");
  };

  return (
    <div className="relative isolate overflow-hidden">
      <div className="absolute inset-x-0 top-0 -z-10 h-112 bg-[radial-gradient(circle_at_20%_20%,rgba(66,156,168,0.2),transparent_32%),radial-gradient(circle_at_80%_0%,rgba(66,156,168,0.14),transparent_28%),linear-gradient(180deg,#fff,#f8fafc_45%,#eef7f8)]" />
      <div className="absolute left-1/2 top-24 -z-10 h-72 w-72 -translate-x-1/2 rounded-full bg-[#429CA8]/10 blur-3xl" />

      <div className="container py-6 sm:py-8">
        <div className="mb-6 flex items-center justify-between gap-3">
          <Button variant="ghost" size="sm" asChild className="rounded-full">
            <Link href={`/${lang}/myHome`}>
              <ArrowLeft className="size-4" />
              {dict.common.back}
            </Link>
          </Button>

          <AddSuccessStoryDialog
            title={dict.successStories.shareDialogTitle}
            description={dict.successStories.shareDialogDescription}
            userAvatar={avatarUrl(currentUser.avatarSeed, 96)}
          />
        </div>

        <section className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]">
          <div className="rounded-[2rem] border border-white/70 bg-white/85 p-6 shadow-[0_24px_80px_rgba(15,23,42,0.08)] backdrop-blur-xl sm:p-8">
            <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.35em] text-[#2b7e87]">
              <Sparkles className="size-4" />
              {dict.successStories.title}
            </div>
            <h1 className="mt-4 max-w-2xl text-3xl font-semibold tracking-tight text-slate-950 sm:text-5xl">
              {dict.successStories.introTitle}
            </h1>
            <p className="mt-4 max-w-3xl text-sm leading-7 text-slate-600 sm:text-base">
              {dict.successStories.introDescription}
            </p>
          </div>

          <FeedFilters
            sortKey={sortKey}
            setSortKey={(value) => startTransition(() => setSortKey(value))}
            isPending={isPending}
            totalStories={stories.length}
            totalMedia={stories.reduce(
              (sum, story) => sum + countMedia(story),
              0,
            )}
          />
        </section>

        <div className="mt-8 grid gap-6 xl:grid-cols-[minmax(0,1fr)_20rem]">
          <div className="space-y-5">
            {visibleStories?.map((story) => (
              <StoryCard
                key={story.id}
                lang={lang}
                story={story}
                liked={likedStoryIds.includes(story.id)}
                onLike={handleLike}
                onComment={handleComment}
                currentUser={currentUser}
                dict={dict}
              />
            ))}
          </div>

          <aside className="hidden xl:block">
            <div className="sticky top-24 space-y-4 rounded-[2rem] border border-white/70 bg-white/90 p-5 shadow-[0_24px_80px_rgba(15,23,42,0.08)]">
              <p className="text-sm font-semibold uppercase tracking-[0.3em] text-muted-foreground">
                Why this section matters
              </p>
              <div className="space-y-4 text-sm text-muted-foreground">
                <p>
                  Stories create trust. Members can show progress, celebrate
                  milestones, and inspire others in the community.
                </p>
              </div>
              <Button
                variant="outline"
                className="w-full rounded-full border-[#429CA8]/20 text-[#2b7e87]"
                asChild
              >
                <Link href={`/${lang}/myHome`}>
                  <ChevronDown className="size-4 rotate-90" />
                  Explore more
                </Link>
              </Button>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
}

